local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[2] = { title = "Klaue von Scharfkralle", description = "Der mächtige Hippogryph Scharfkralle wurde getötet und die Klaue der erschlagenen Bestie dient als Beweis für Euren Sieg. Senani Thunderheart im Splintertreeposten wird zum Beweis Eurer Tat sicher gern diese Trophäe sehen wollen.", objectives = "Bringt die Klaue von Scharfkralle zu Senani Thunderheart im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5] = { title = "Jitters' knurrender Magen", description = "Ich verstecke mich jetzt schon seit Wochen in dieser Geisterstadt, und die ganze Zeit habe ich nichts gegessen außer Maden und Unkraut! Ich brauche was Anständiges zum Essen, und ich werde mich nicht lumpen lassen.\n\nBringt mir ein Festessen, und ich bezahle Euch gut dafür.\n\nIch habe gehört, dass Küchenchef Grual aus der Taverne Zum roten Raben in Dunkelhain ganz ausgezeichnete schwärzliche Krebsküchlein macht...", objectives = "Sprecht mit Küchenchef Grual.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6] = { title = "Kopfgeld auf Garrick Padfoot", description = "Garrick Padfoot, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!\n\nDoch seht Euch vor, $N. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.", objectives = "Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7] = { title = "Säuberung im Koboldlager", description = "Eure erste Aufgabe ist eine Säuberung, $n. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", objectives = "Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8] = { title = "Ein Schurkenhandel", description = "Heda, Kamerad! Wollt Ihr nicht einem jungen Mann, der mehr als seinen Teil an hirnlosen Zombies und Spinnen umgelegt hat, einen Gefallen tun?\n\nIch hab hier einen Brief, der muss nach Brill... zu so einer Gastwirtin namens Renee Irgendwas. Ist eigentlich völlig egal, wie sie mit Nachnamen heißt.\n\nNa egal, jedenfalls ist es ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort für Euch, an dem Ihr Euch ausruhen könnt, falls das mal nötig wird. Ihr solltet Euch den wirklich mal anseh'n - macht es, und ich bezahl Euch auch noch gut dafür.", objectives = "Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9] = { title = "Tod auf den Feldern", description = "Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht! Jetzt sieht es allerdings so aus, als hätten einige Erntebehüter sich in den Feldern breit gemacht.\n\nWenn Ihr Euch dem gewachsen fühlt, dann geht hinaus und tötet dort draußen 20 von ihnen. Wenn Ihr fertig seid, kommt zurück und holt Euch Eure Bezahlung ab. Und wenn Ihr alle in meinem Feld erwischt habt, dann räumt auch in den angrenzenden Feldern auf.", objectives = "Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[10] = { title = "Die Erlösung von Scrimshank", description = "Oh, das ist einfach schrecklich! Ich habe meinen besten Gehilfen, Unterfeldmesser Scrimshank, in die Wüste südöstlich von hier geschickt. Das ist ein Gebiet, das wir die Klaffende Schlucht nennen. Nun ja, er wird vermisst und in seinem letzten Bericht sprach er davon, dass es dort, wo er war, noch mehr dieser komischen Viecher gäbe. Könnte es sein, dass sie sich jetzt in zwei großen Gebieten der Wüste eingenistet haben?\n\nBegebt Euch bitte für mich zur Klaffenden Schlucht und sucht nach Scrimshank! Das... oder findet wenigstens seine Feldmesserausrüstung. Ich fürchte, das ist alles, was von dem Armen übrig geblieben ist.", objectives = "Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[11] = { title = "Kopfgeld auf die Flusspfotengnolle", description = "Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertig werden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet. Eine weitere Gruppe hat sich im Gebiet nahe des Steinhügelsees im Osten eingenistet.\n\nDie Armee von Stormwind wird jeden belobigen, der dabei hilft, die Gnolle zu töten. Bringt mir ihre bemalten Gnoll-Armbinden als Beweis für Eure Tat.", objectives = "Bringt Deputy Rainer in der Kaserne 8 bemalte Gnoll-Armbinden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[12] = { title = "Die Volksmiliz", description = "Die Volksmiliz hat nur ein einziges Ziel: Westfall zu verteidigen und den Frieden in dieses Land zurückzubringen. Doch leider muss der Frieden nur allzu oft mit Blut bezahlt werden. \n\nEiner meiner Späher hat uns Kunde davon gebracht, dass eine Fallenstellerbande der Defias hier in der Nähe verheerende Schäden anrichtet. Mir liegen Berichte vor, dass einige Fallensteller der Defias in der Nähe des Jangoschachts im Nordwesten gesichtet wurden, ebenso bei Molsens Hof und bei Furlbrows Kürbishof. Wenn Ihr unseren Reihen beizutreten wünscht, dann erschlagt 15 Fallensteller der Defias und 15 Schmuggler der Defias und kehrt zu mir zurück.", objectives = "Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[13] = { title = "Die Volksmiliz", description = "Eine Bande heimtückischer Plünderer der Defias ist dabei gesehen worden, wie sie den Goldküstensteinbruch, Moonbrook und Alexstons Bauernhof ausplünderten. Die Volksmiliz kann ein solches Verhalten nicht hinnehmen. Macht Euch unverzüglich auf den Weg, $N, und zeigt, dass das Licht in Westfall zugegen ist.\n\nDer Goldküstensteinbruch befindet sich in der Nähe der Küste, westlich vom Turm. Im nächsten Schritt Eurer Ausbildung müsst Ihr 15 dieser üblen Plünderer der Defias und 15 Ausplünderer der Defias töten.", objectives = "Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[14] = { title = "Die Volksmiliz", description = "Einige Defias konnten wir bislang nicht erwischen. Mein bester Späher berichtet, dass diese Defias in der ganzen Gegend auf Raubzug gehen und schon bis Süd-Westfall gekommen sind. Wir glauben, dass sie sich in den Dolchhügeln versteckt halten und dort ihren nächsten Schachzug planen. Schaltet diese Verbrecher im Namen der Volksmiliz aus.", objectives = "Gryan Stoutmantle möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[15] = { title = "Überprüfung der Echokammmine", description = "Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, $N. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.\n\nBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 10 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.", objectives = "Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[16] = { title = "Etwas zu trinken für Gerard", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[17] = { title = "Reagenzsuche in Uldaman", description = "Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.\n\nFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", objectives = "Bringt zwölf magenta Funguskappen nach Thelsamar zu Ghak Healtouch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[18] = { title = "Bruderschaft der Diebe", description = "Seit kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.\n\nIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.", objectives = "Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[19] = { title = "Tharil'zun", description = "Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten der Blackrock ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben. Bringt mir den Kopf von Tharil'zun!", objectives = "Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marshal Marris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[20] = { title = "Bedrohung durch die Blackrock", description = "Die Orcs des Blackrockklans haben die brennende Steppe verlassen und Burg Steinwacht im Norden besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von Seenhain, so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch.\n\nHelft uns, diese Bedrohung von Seenhain zu nehmen! Tötet diese Orcs der Blackrock und bringt mir 10 ihrer kampferprobten Äxte zum Beweis.\n\nUnd obwohl die Blackrocks uns vor allem aus dem Norden bedrohen, haben wir auch gehört, dass sich noch weitere in der südöstlichen Ecke des Rotkammgebirges aufhalten. Wenn Ihr dort welche findet, solltet Ihr die auch jagen.", objectives = "Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[21] = { title = "Scharmützel in der Echokammmine", description = "Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien.\n\nIhr dürft keine Zeit verlieren, $n. Je länger die Kobolde sich ungehindert in der Mine aufhalten können, umso festere Wurzeln fassen sie in Nordhain.", objectives = "Tötet 12 Koboldhilfsarbeiter und kehrt dann zu Marshal McBride in der Abtei von Nordhain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[22] = { title = "Pastete aus Geiferzahnleber", description = "Die Zwiebeln sind geschält, der Knoblauch ist gehackt, der Rosmarin ist zerstoßen, die Kruste ist gebacken, das Dillkraut ist gewiegt und die Sauce steht auf dem Herd. Jetzt brauche ich für meine berühmte Fleischpastete nur noch 8 Geiferzahnlebern!", objectives = "Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[23] = { title = "Ursangus' Tatze", description = "Die Tatze des mächtigen Bären Ursangus stellt die Trophäe für diesen Teil der Jagd in Ashenvale dar. Auf der Tatze befindet sich ein kleines Halbmond-Emblem; die Bedeutung dieses Emblems bleibt jedoch ein Geheimnis.\n\nDie Tatze soll zu Senani Thunderheart im Splintertreeposten gebracht werden, um zu beweisen, dass Ihr das mächtige Tier besiegt und diesen Teil der Jagd abgeschlossen habt.", objectives = "Bringt Ursangus' Tatze zu Senani Thunderheart im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[24] = { title = "Schattumbras Kopf", description = "Der einstmals so flinke Schattumbra liegt jetzt regungslos vor Euch und der Sieg ist Euer. Der Kopf des erschlagenen Nachtsäblers ist eine passende Trophäe für diesen Kampf. Senani Thunderheart im Splintertreeposten wird eine solche Trophäe sehen wollen, um Euch den Erfolg in diesem Teil der Jagd in Ashenvale anzurechnen.", objectives = "Bringt Schattumbras Kopf zu Senani Thunderheart im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[25] = { title = "Stillstand am Steinkrallenpfad", description = "Wenn Ihr Euch nützlich machen wollt, warum unternehmt Ihr dann nicht etwas wegen der Situation am Steinkrallenpfad?\n\nDer Güterverkehr zwischen Ashenvale und dem Steinkrallengebirge steht still, weil der See zum Leben erwacht ist und alles angreift, was ihm zu nahe kommt... und das bedeutet, jeden auf dem Pfad. Noch weitaus nützlicher als einfach nur die Wasserelementare zu unterjochen, wäre es, wenn jemand den Pavillon auf dem Mystralsee auskundschaften würde... der, von dem aus man einen guten Blick auf den dortigen Außenposten der Allianz hat.\n\nNa, wollt Ihr Euch nützlich machen?", objectives = "Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splintertreeposten.\n\nErkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.\n\nKehrt zu Mastok Wrilehiss im Splintertreeposten in Ashenvale zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[26] = { title = "Eine wertvolle Lektion", description = "$N, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", objectives = "Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[27] = { title = "Eine wertvolle Lektion", description = "$N, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", objectives = "Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[28] = { title = "Prüfung des Sees", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, $N.", objectives = "Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[29] = { title = "Prüfung des Sees", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, $N.", objectives = "Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[30] = { title = "Prüfung des Seelöwen", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", objectives = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[31] = { title = "Wassergestalt", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runetotem nach Thunder Bluff zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", objectives = "Kehrt nach Thunder Bluff zurück und zeigt Turak Runetotem den Anhänger des Seelöwen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[32] = { title = "Aufstieg der Silithid", description = "Hier ist Euer Bericht. Ihr solltet damit zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da einen Troll-Gelehrten mit Namen Zilzibin Drumlore. Er hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und er ist noch dazu Historiker! Wenn Euch jemand helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und wie sie zu stoppen ist, gebt ihm diesen Bericht. Hilfe können wir gar nicht genug haben.\n\nZil lebt in einem Haus auf der zweiten Ebene der Gasse in Orgrimmar.", objectives = "Bringt den Bericht nach Orgrimmar zu Zilzibin Drumlore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[33] = { title = "Wölfe an der Grenze", description = "Ich hasse diese grässlichen Waldwölfe! Aber Wolfsteaks esse ich für mein Leben gern. Bringt mir zähes Wolfsfleisch, dann gebe ich Euch etwas dafür, das Euch von Nutzen sein wird.\n\nZähes Wolfsfleisch bekommt Ihr, wenn Ihr die Waldwölfe und jungen Wölfe jagt, die in Nordhain durch das Land streifen.", objectives = "Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[34] = { title = "Ein ungebetener Gast", description = "Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marshal Marris seit einer Weile immer \"Stopfwanst\" nennt.\n\nJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen diesem einen gefährlichen Eber. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.", objectives = "Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[35] = { title = "Weitere Sorgen", description = "Falls Ihr befürchtet, dass die Gerüchte über das Auftauchen von Murlocs wahr sein könnten, dann tut das Folgende: Begebt Euch zur östlichen Elwynn-Brücke und sprecht mit Wache Thomas. Er ist seit einer Woche an der Brücke stationiert und wird deswegen wissen, wie es in der Gegend aussieht.\n\nBringt mir seinen Bericht.", objectives = "Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[36] = { title = "Westfall-Eintopf", description = "Ich hätte nie gedacht, dass jemals der Tag kommen würde, an dem ich den Hof verlasse. Aber in den Feldern wimmelt es nur so von Dieben und es ist hier für uns viel zu gefährlich geworden. Sobald Bauer Furlbrow den Wagen repariert hat, machen wir uns auf den Weg. \n \nKönntet Ihr mir vielleicht einen Gefallen tun? Ich schreibe Euch schnell mein Rezept für Westfall-Eintopf auf. Seid so nett und bringt es Salma Saldean; sie wohnt auf dem Hof dort hinten. Ihr findet den Hof der Saldeans gleich hinter der Gabelung der Straße.", objectives = "Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[37] = { title = "Suche nach den vermissten Wachen", description = "Vor ein paar Tagen haben wir zwei Wachen, Rolf und Malakai, losgeschickt, damit sie entlang des Flusses Nachforschungen anstellen, aber bisher sind sie noch nicht zurückgekehrt. Damit ich meinen Bericht fertig schreiben kann, muss ich wissen, was den beiden Männern zugestoßen ist.\n\nSucht den Fluss in Richtung Norden ab und seht zu, dass Ihr die Wachen findet... oder ihre Überreste...", objectives = "Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[38] = { title = "Westfall-Eintopf", description = "Wollt Ihr mir dabei helfen, Westfall-Eintopf zu kochen? Dann bringt mir die folgenden Zutaten: \n \n 3 Stücke sehniges Geierfleisch \n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", objectives = "Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[39] = { title = "Zustellung von Thomas' Bericht", description = "Berichtet Marshal Dughan, dass Malakai und Rolf ums Leben gekommen sind, und teilt ihm auch mit, dass wir die Murlocs in Ost-Elwynn mit unserer derzeitigen Truppenstärke hier nicht unter Kontrolle halten können.\n\nIch weiß, dass wir nicht viele überzählige Männer haben, aber vielleicht findet Dughan ja doch jemanden.", objectives = "Erstattet Marshal Dughan in Goldhain Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[40] = { title = "Gefahr aus dem Wasser", description = "Eine neue Gefahr bedroht den Wald von Elwynn, $N! Murlocs kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an!\n\nIch habe Marshal Dughan bereits gewarnt, aber der macht sich größere Sorgen wegen der Gnolle und der Banditen. Er ist nicht überzeugt davon, dass die Murlocs eine Gefahr darstellen.\n\nBitte sprecht mit Dughan, $N, und bringt ihn dazu, dass er Verstärkung in den Osten schickt!", objectives = "Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marshal Dughan sprecht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[45] = { title = "Rolfs Schicksal", description = "Als Ihr die Gegend weiter absucht, findet Ihr die Abdrücke von Füßen mit Schwimmhäuten, die entlang dem Ufer des Steinhügelsees nach Osten führen. In der Ferne könnt Ihr im Osten gerade noch so ein Murlocdorf ausmachen.\n\nVielleicht fand Rolfs Leben dort sein Ende...", objectives = "Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[46] = { title = "Kopfgeld auf die Murlocs", description = "Die Armee von Stormwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt mir ihre zerrissenen Murlocflossen, dann wird die Armee von Stormwind Euch ansehnlich belohnen\n\nDie Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.", objectives = "Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den ihr an der östlichen Elwynn-Brücke findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[47] = { title = "Tauschhandel mit Goldstaub", description = "Manchmal haben die Kobolde in dieser Gegend Goldstaub dabei. Das Zeug könnte ich wirklich gut gebrauchen. Bringt mir etwas davon und ich mache Euch den besten Preis in der Stadt... den besten Preis in der Stadt!\n\nDie Kobolde halten sich in der Tiefenschachtmine im Süden und im Bereich der Jaspismine im Nordosten auf.", objectives = "Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[48] = { title = "Goldbrauner Samt", description = "Weit im Süden, wo die Lianen sich ranken,\nLiegt versteckt ein Brunnen, in dem fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", objectives = "Bringt Grimbooze Donnerbräu Wasser von der Heiligen Quelle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[49] = { title = "Goldbrauner Samt", description = "Lang schon vermiss ich die Lieb meines Lebens,\nGoldbraun und samtig, doch noch wart ich vergebens.\nBringt mir, dann vergeht jeder Zorn,\nJe einen Sack Gerste, Roggen und Korn.", objectives = "Grimbooze Donnerbräu möchte einen Sack Gerste, einen Sack Roggen und einen Sack Korn haben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[50] = { title = "Goldbrauner Samt", description = "Die Maische anrühren, das ist mein Wille,\nDoch fehlt mir dann auch noch eine Destille.\nFür diese brauch ich ein starkes Metall - \nBringt mir Echtsilber, das ist gut in dem Fall!", objectives = "Grimbooze Donnerbräu braucht Echtsilber.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[51] = { title = "Goldbrauner Samt", description = "Noch ist er nicht fertig, doch schon frisch gebrannt,\nJetzt wird als Nächstes der Meiler bemannt,\nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", objectives = "Bringt Grimbooze Donnerbräu den Ast eines Bergahorns.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[52] = { title = "Grenzschutz", description = "Seid gegrüßt, $n. Je weiter wir uns von Goldhain entfernen, umso reizbarer sind die wilden Tiere. Und das Holzfällerlager des Osttals wird beinahe ständig von Wölfen und Bären angegriffen.\n\nWir könnten hier draußen wirklich Eure Hilfe gebrauchen.", objectives = "Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Elwynn-Brücke zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[53] = { title = "Goldbrauner Samt", description = "Das Getränk, das ich braue, das reine und klare,\nWird goldbraun und samtig im Laufe der Jahre.\nDoch ehe er fertig, der Whisky, der weiche,\nBraucht's noch ein Fass aus verkohlter Eiche.", objectives = "Bringt Grimbooze Donnerbräu ein verkohltes Eichenbündel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[54] = { title = "Meldung in Goldhain", description = "$N, Ihr habt bewiesen, dass Ihr als $C Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.\n\nWenn Ihr Euch dieser Aufgabe stellen wollt, dann nehmt diese Papiere, die bei Marshal Dughan in Goldhain abgeliefert werden müssen. Goldhain liegt an der südlichen Straße, hinter den Grenztoren.", objectives = "Liefert Marshal McBrides Unterlagen bei Marshal Dughan in Goldhain ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[55] = { title = "Morbent Teufel", description = "Morbent Fel hält sich in seinem Unterschlupf verborgen, dem Haus, das hoch oben auf dem Hügel im Osten über dem Friedhof von Rabenflucht thront. Doch seine Zeit in diesem Land neigt sich dem Ende entgegen...\n\nSetzt Morbents Bann gegen ihn ein. Das wird seine schützenden Zauber machtlos machen.\n\nErschlagt ihn. Erschlagt ihn und errettet uns von seiner Verderbtheit. Werdet zum Instrument meiner Rache und damit $gzum Helden:zur Heldin; des Dämmerwalds!", objectives = "Verwendet Morbents Bann gegen Morbent Fel, tötet Morbent Fel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[56] = { title = "Die Nachtwache", description = "Als Kommandantin der Nachtwache habe ich geschworen, die Bürger von Dunkelhain zu beschützen. Stormwind hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind wir uns selbst überlassen.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, könnten wir Eure Hilfe wirklich gebrauchen! Helft der Nachtwache und wagt Euch in den Friedhof \"Stille Gärten\", der ein Stückchen südlich von Dunkelhain liegt. Tötet dort 8 Skelettkieger und 6 Skelettmagier. Der Bedrohung durch die Untoten muss ein Ende gemacht werden!", objectives = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[57] = { title = "Die Nachtwache", description = "Ich habe berichtet bekommen, dass im Wald eine wahre Untotenplage ausgebrochen ist, $N. Wenn Ihr Euch der Aufgabe gewachsen fühlt, dann macht Euch auf den Weg zum Friedhof von Rabenflucht und erschlagt 15 dieser abscheulichen Skelettsatanskreaturen und 15 Skelettschrecken. Außerdem sollen im Friedhof \"Stille Gärten\", der sich ein Stückchen südlich von Dunkelhain befindet, Skelette gesehen worden sein. Die Untoten müssen aus dem Dämmerwald vertrieben werden!", objectives = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 15 Skelettsatanskreaturen und 15 Skelettschrecken tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[58] = { title = "Die Nachtwache", description = "Die Lage in Rabenflucht ist noch immer sehr bedenklich. Die Sicherheit von Dunkelhain liegt in Euren Händen, $N. Ich habe einfach nicht genug Behüter, um die Sicherheit in der Stadt zu gewährleisten. Deswegen müsst Ihr Euch erneut nach Rabenflucht aufmachen und das östliche Mausoleum von den Seuchenverbreitern säubern, die sich dort breit gemacht haben. Tötet 20 von ihnen!", objectives = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr im östlichen Mausoleum von Rabenflucht 20 Seuchenverbreiter tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[59] = { title = "Rüstung aus Tuch und aus Leder", description = "Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Timberlain. Wenn Ihr ihr den Gutschein gebt, dann stellt sie die Rüstung für Euch her. Und wenn Ihr sie habt, tragt sie zur Verteidigung von Elwynn, $N.\n\nIhr findet das Holzfällerlager des Osttals im Osten jenseits von Wache Thomas' Posten.", objectives = "Gebt Sara Timberlain den Rüstungsgutschein der Armee von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[60] = { title = "Koboldkerzen", description = "Guten Tag, $gwerter Herr:werte Dame;! Hättet Ihr einen Moment Zeit für mich?\n\nMein Bruder und ich führen in Stormwind eine Apotheke und ich bin hier, weil ich große Kerzen suche, ihres Wachses wegen. Könnt Ihr mir vielleicht helfen?\n\nGroße Kerzen könnt Ihr von Kobolden bekommen - und ich habe Gerüchte gehört, dass Kobolde sich in den Minen von Elwynn eingenistet haben: in der Tiefenschachtmine im Süden und in der Jaspismine im Osten. Ich schlage vor, dass Ihr Euch an einem dieser Orte auf die Suche nach Kerzen begebt.", objectives = "Bringt 8 große Kerzen nach Goldhain zu William Pestle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[61] = { title = "Lieferung nach Stormwind", description = "In Stormwind wartet mein Bruder Morgan auf die Lieferung der Kerzen. Ich habe selbst nicht die Zeit, um mich auf die Reise zu begeben, aber wenn Ihr ihm die Lieferung überbringen wollt, so wird er Euch gut bezahlen.\n\nIch habe die Kerzen schon fertig verpackt. Ihr findet Morgan in unserem Geschäft im Handelsdistrikt von Stormwind. Es heißt Pestles Apotheke.", objectives = "Bringt Williams Lieferung in den Handelsdistrikt von Stormwind zu Morgan Pestle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[62] = { title = "Die Tiefenschachtmine", description = "Die Mine in Nordhain ist nicht die einzige, mit der es Probleme gibt. Berichten zufolge ist auch die Tiefenschachtmine im Wald von Elwynn zu einem Tummelplatz für Kobolde geworden.\n\nErforscht die Mine, bestätigt diese Berichte und kehrt dann zu mir zurück. Die Mine liegt fast genau südlich von Goldhain, zwischen den Höfen der Stonefields und der Maclures.", objectives = "Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marshal Dughan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[63] = { title = "Ruf des Wassers", description = "An der Küste des Silberwalds befindet sich westlich des Grabmals ein Schrein, der von der Seuche besudelt ist. Die Geister dort sprechen nicht länger zu unserem Volk und es ist jetzt an Euch, die Manifestation dort zu besiegen und den Teich zu säubern.\n\nNehmt die Armschienen des Elementars und gebt sie zusammen mit den verbleibenden Tropfen von Brines Trank in die Kohlenpfanne. Das sollte ausreichen, um einen reinen Geist zu beschwören, mit dem Ihr kommunizieren könnt.\n\nBringt mir einen Beweis dafür, dass Ihr die Tat vollbracht habt, dann belohne ich Euch mit Eurem Totem.", objectives = "Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Everfount.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[64] = { title = "Das vergessene Erbstück", description = "Es war fürchterlich! Verna hat mich aufgeweckt, als sie draußen auf dem Feld so einen Radau gehört hat. Das ganze Feld war voller Rowdys! Wir sind in solcher Eile aufgebrochen und da hab ich vergessen, meine Taschenuhr einzupacken. Die Uhr hat mir Vernas Vater an unserem Hochzeitstag geschenkt und es wird mir fast schlecht, wenn ich dran denke, dass diese Diebe sie jetzt haben. Ich hab die Taschenuhr im Kleiderschrank in unserem Haus liegen lassen. Haltet nach dem Kürbisfeld im Westen Ausschau, dann kommt Ihr zu unserem Hof - Ihr könnt ihn gar nicht verfehlen. Wenn Ihr mir meine Uhr wiederbringen würdet, wäre ich Euch sehr dankbar.", objectives = "Bauer Furlbrow möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[65] = { title = "Die Bruderschaft der Defias", description = "Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.\n\nBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt.", objectives = "Gryan Stoutmantle möchte, dass Ihr in Seenhain mit Wiley sprecht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[66] = { title = "Die Legende von Stalvan", description = "Letzte Nacht verspürte ich in meinem Geist eine schreckliche Erschütterung. Ich wusste, dass sich meine Enkelin Alyssa in großer Gefahr befand. Ich befragte die Karten und aus ihnen starrte mich die Fratze des Todes höhnisch an.\n\nIch begab mich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es mir, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich mir, der Name Stalvan.\n\nSucht den Amtmann im Rathaus auf und schaut, ob Ihr nicht mehr über diese Person herausfinden könnt. Ich fürchte um unser aller Leben.", objectives = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[67] = { title = "Die Legende von Stalvan", description = "Stalvan, hm? Lasst mich im Stadtverzeichnis nachsehen.\n\nStalvan... Stalvan... mal sehen. Ah, hier ist es! Ich habe hier einen Eintrag über einen gewissen Stalvan Mistmantle. Die letzte bekannte Adresse ist die Schule in Moonbrook. Liebe Güte, das nenne ich veraltet!\n\nWürdet Ihr mir einen Gefallen tun? Falls Ihr zufällig nach Moonbrook kommt, dann lasst es mich wissen, wenn Ihr an neue Informationen über diese Person geraten solltet. Ich habe meine Unterlagen gern auf dem neuesten Stand.", objectives = "Begebt Euch zur Schule in Moonbrook und bringt Amtmann Daltry alle neuen Informationen über Stalvan Mistmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[68] = { title = "Die Legende von Stalvan", description = "In der alten Schließkiste findet Ihr einen verstaubten, nie abgeschickten Brief.", objectives = "Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[69] = { title = "Die Legende von Stalvan", description = "Ach du liebes bisschen! Das ist mir beim ersten Mal ja glatt entgangen! Hier im Verzeichnis steht beim Eintrag für diesen Stalvan direkt unter der ersten Adresse noch eine weitere, die zum Teil durchgestrichen ist. Es scheint, als wäre er zum Gasthaus Zur Höhle des Löwen drüben in Goldhain unterwegs gewesen. Vielleicht solltet Ihr dort nachfragen, $N.", objectives = "Begebt Euch zum Gasthaus Zur Höhle des Löwen und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[70] = { title = "Die Legende von Stalvan", description = "Den Namen Stalvan hab ich schon mal gehört... Ach, jetzt fällt's mir wieder ein.\n\nVor vielen Jahren betrat an einem stürmischen Abend ein Bote dieses Haus, der Unterkunft für die Nacht suchte. Es war noch nicht ganz Mitternacht, da kam der Mann schreiend die Treppe heruntergerannt. Er war bleich wie der Tod vor Angst. Nur mit seinem Nachtgewand bekleidet verschwand er im Regen.\n\nIn der Eile vergaß er seine Briefe in der Truhe oben und kam nie zurück, um sie abzuholen. Es ist ein Brief dabei von diesem Stalvan, den Ihr erwähntet, adressiert an den Kanaldistrikt in Stormwind. Ihr dürft ihn gern haben.", objectives = "Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Stormwind ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[71] = { title = "Meldung an Thomas", description = "Nun habt Ihr beide Medaillons. Bringt sie an die Brücke zu Wache Thomas, damit er erfährt, welches Schicksal seine beiden Kameraden erlitten haben.", objectives = "Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Elwynn-Brücke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[72] = { title = "Die Legende von Stalvan", description = "Mein Vater war der Verwalter des Besitzes, lange bevor ich es wurde. Nach dem Massaker war er derjenige, der das Blut aufwischen und aufräumen musste. Aber das tut nichts zur Sache.\n\nDie letzten Gelder aus dem Flintridge-Fonds sind versiegt und jetzt müssen die letzten Stücke aus dem Familienbesitz versteigert werden. Daran sind nur diese Steuereintreiber schuld. Aber wenn Ihr wirklich dringend mehr erfahren wollt, dann dürft Ihr diesen Kram hier gern durchsehen. Wer weiß, was Ihr findet.", objectives = "Durchsucht die verpackten Besitztümer nach Hinweisen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[74] = { title = "Die Legende von Stalvan", description = "In der Kiste findet Ihr verschiedene Dinge: muffige Erbstücke, ein Familienportrait, einige Jagdtrophäen und ein paar alte Bücher. Fast schon am Boden der Kiste findet Ihr unter einer Keramikvase eine zerrissene Tagebuchseite.", objectives = "Die zerrissene Tagebuchseite, die Ihr gefunden habt, gibt Euch den nächsten Hinweis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[75] = { title = "Die Legende von Stalvan", description = "Als ich hier eingezogen bin, stand oben schon eine Truhe mit Pergamenten darin. Kurz nach meinem Einzug habe ich sie mir einmal angesehen, aber bald darauf konnte ich nur noch verschwommen sehen und da hab ich's dann gelassen. \n\nTut einem alten, halb blinden Mann einen Gefallen und seht Euch selbst mal in der Kiste oben um, ob Ihr vielleicht etwas findet, das Euch bei Eurer Suche nach diesem Stalvan weiterhelfen kann. Ich bin mir ziemlich sicher, dass da eine verblasste Tagebuchseite dabei ist, die Euch interessieren müsste. Bringt sie mir und ich werde sehen, was ich tun kann, um Euch zu helfen.", objectives = "Marshal Haggard möchte, dass Ihr in der Kiste oben nach der verblassten Tagebuchseite sucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[76] = { title = "Die Jaspismine", description = "Dank Euch wissen wir jetzt, dass Kobolde sich in der Tiefenschachtmine eingenistet haben. Jetzt brauchen wir noch einen Späher, der die weiter entfernte Jaspismine untersucht.\n\nErforscht die Jaspismine und bestätigt mir, ob sich dort tatsächlich Kobolde aufhalten. Die Mine erreicht Ihr, indem Ihr der Straße nach Osten folgt, bis Ihr zum Turm von Azora kommt. Wenn Ihr Euch am Turm nach Norden wendet, dann findet Ihr die Mine im Vorgebirge.", objectives = "Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marshal Dughan zurück, um ihm Bericht zu erstatten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[77] = { title = "Eine schwierige Situation", description = "Ich besitze Originalverpackungsmaterial für die Welle, die Dran Droffers will. Ich werde Euch dabei helfen, die Welle für Maltons ungehobelten Vater zu verpacken... für einen Unkostenbeitrag in Höhe zweier weiterer Flaschen besagter Welle. Sie befinden sich in Kisten, die Ihr in dem verlassenen Stützpunkt der Horde in der Nähe von Skulk Rock findet.\n\nDas heißt, dass es eine anstrengende Aufgabe wird. Ihr werdet bei den Ruinen stinkende Brühschleimer und Brühschlammer vorfinden; angeblich werden sie von einer Art Oberbrühschlammer geführt. Beschafft trotzdem die Welle und kehrt hierher zu mir zurück, um sie zu verpacken.", objectives = "Holt 10 Flaschen Hinterland-Honigwelle aus den Kisten, die sich rund um den verlassenen Stützpunkt der Horde in Skulk Rock befinden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[78] = { title = "Die Legende von Stalvan", description = "Ich kenne jemanden, der Euch vielleicht helfen könnte. Damals, als ich noch die Wachen von Stormwind kommandierte, haben wir immer in der Taverne Zum roten Raben in Dunkelhain gesessen und etwas getrunken. Smitts, der Gastwirt dort, kannte sich mit den örtlichen Lehren ziemlich gut aus. Zeigt ihm diese Seite, mal sehen, was er dazu zu sagen hat.", objectives = "Bringt die verblasste Tagebuchseite zu Schankwart Smitts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[79] = { title = "Die Legende von Stalvan", description = "Ich habe die Geschichten um diesen Stalvan jahrelang verfolgt. Als vor ein paar Jahren diese Adligen, die hier zu Besuch waren, ermordet wurden, hab ich Haggard bei seinen Nachforschungen begleitet. Ich habe damals diese schlammverschmierten Seiten gefunden, aber es ist uns nie gelungen, die Handschrift mit diesem Verrückten in den Wäldern in Verbindung zu bringen. Eure Spur der Beweise zeigt aber, dass er schuldig ist. Bringt dies sofort zu Kommandant Ebonlocke und sagt ihr, was Ihr entdeckt habt!", objectives = "Bringt Kommandant Ebonlocke die schlammverschmierte Seite.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[80] = { title = "Die Legende von Stalvan", description = "Ich beobachte diesen Widerling Stalvan jetzt schon eine ganze Weile. Aber wenn diese Seite tatsächlich von seiner Hand geschrieben wurde, dann beweist das seine Schuld ohne den letzten Zweifel.\n\nSo lange, wie Amtmann Daltry das Stadtverzeichnis jetzt schon verwaltet, ist er ein wahrer Experte darin geworden, Handschriften zu identifizieren. Zeigt ihm diese Seite und stellt fest, ob die Schrift dieselbe ist wie diejenige der Unterschrift im Verzeichnis.", objectives = "Zeigt Amtmann Daltry die blutbefleckte Tagebuchseite.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[81] = { title = "Wellenlieferung", description = "Ich habe zusätzliche Vorsichtsmaßnahmen getroffen und nicht nur Drans verpackte Welle in dem Fass sicher untergebracht, sondern auch die zusätzlichen Wellenflaschen, die er klaut. Auch wenn ich nicht viel von Dran halte, so gibt es doch nichts Schlimmeres als ein durchgeschütteltes Wellenbouquet. Bitte, bitte, keine Ursache.\n\nBringt jetzt Euer Fass zu Dran Droffers in seinem Kramladen in Orgrimmar. Entbietet meine besten Grüße bitte auch Malton und lasst ihn wissen, dass uns sein Besuch eine große Ehre wäre, falls es ihn jemals nach einem feinen Getränk und noch feineren Trinkkumpanen gelüstet.", objectives = "Liefert das Fass nach Orgrimmar an Dran Droffers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[82] = { title = "Erkundung des Giftigen Unterschlupfes", description = "Tja, diese Berichte über die Käfer... wir wissen, dass sie die Teiche trocken legen, die sich dort befanden, wo sich der Giftige Unterschlupf befindet. Was wir NICHT wissen, ist, na ja, alles andere.\n\nWir müssen als Erstes herausfinden, wer unser Feind ist! Begebt Euch bitte in den Giftigen Unterschlupf und besorgt ein paar Stücke dieser Tierwesen. Holt fünf der dortigen Centipaar und bringt sie dem Alchimisten Pestlezugg zur Untersuchung. Wenn er sich damit beschäftigt, werden wir schon herausfinden, worum es sich handelt!", objectives = "Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchimisten Pestlezugg.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[83] = { title = "Rote Leinenwaren", description = "Die Mitglieder der Defias in Nordhain tragen Masken aus Sackleinen, die Masken der Defias in Elwynn dagegen sind aus gutem Leinen, aus dem ich Qualitätsleinenwaren herstellen kann.\n\nBringt mir rote Leinenkopftücher, dann stelle ich daraus etwas für Euch her.\n\nDie Mitglieder der Defias haben Lager, die sich über ganz Elwynn verteilen.", objectives = "Bringt 6 rote Leinenkopftücher ins Holzfällerlager des Osttals zu Sara Timberlain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[84] = { title = "Zurück zu Billy", description = "Hier, bitte schön. Und wenn Ihr Billy die Pastete gebt, dann sagt ihm, ich hoffe, er erstickt daran!", objectives = "Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[85] = { title = "Die verlorene Halskette", description = "Ich habe meine Halskette verloren und ich glaube, dieser Tunichtgut Billy Maclure hat sie genommen! Normalerweise treibt er sich immer wie eine kleine Ratte in den Weinbergen der Maclures östlich von hier herum. \n\nBringt mir meine Halskette zurück, wenn Ihr das Herz einer alten Witwe erfreuen wollt.", objectives = "Sprecht mit Billy Maclure.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[86] = { title = "Pastete für Billy", description = "Wenn ich 'ne Pastete kriegen würde, dann könnte ich Euch vielleicht sagen, wer die Kette hat. Ach, und wisst Ihr was? Diese alte Dame Bernice auf dem anderen Hof da macht ganz tolle Schweinebauchpasteten. \n\nWenn Ihr ihr ein paar Brocken Eberfleisch von den Ebern bringt, die immer um unsere Höfe herumstromern, und ihr sagt, dass es für einen guten Zweck ist, dann backt sie Euch vielleicht eine Pastete.", objectives = "Bringt 4 Brocken Eberfleisch zu Tantchen Bernice Stonefield auf den Hof der Stonefields.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[87] = { title = "Goldzahn", description = "Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallen ge... äääh, gesehen. Fragt mich nicht, wie die dahin gekommen ist, ich war's nicht!\n\nNa egal, jedenfalls hab ich diesen großen Kobold gesehen, der hatte einen Goldzahn und der hat die Kette aufgehoben und ist in die Mine gerannt. Wenn Ihr diesen Kobold findet, dann findet Ihr auch die Halskette, ehrlich! Ich schwör's!", objectives = "Bringt Berenices Halskette auf den Hof der Stonefields zu \"Tantchen\" Berenice Stonefield.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[88] = { title = "Prinzessin muss sterben!", description = "Die Brackwells haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst!\n\nUnd deswegen muss Prinzessin sterben, bevor sie wieder unsere Felder heimsucht! Bringt mir ihr Halsband zum Beweis, dass Ihr die Sau abgestochen habt, dann gebe ich Euch etwas, das Euch für Euren Aufwand entschädigt.\n\nIhr findet Prinzessin normalerweise bei Brackwells Kürbisbeet, noch hinter dem Hof der Maclures und von dort aus im Osten gesehen. Ich hoffe, Ihr erwischt die Sau, bevor sie wieder hungrig wird und hierher kommt!", objectives = "Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Stonefield auf den Hof der Stonefields.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[89] = { title = "Die Immerruhbrücke", description = "Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Wir haben Stormwind benachrichtigt, dass wir eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen.\n\nJetzt gehen uns langsam die Vorräte aus, die wir brauchen, um die Brücke wieder aufzubauen. Wenn Ihr mir 5 Eisenspitzen und 5 Eisennieten bringt, $N, dann sollt Ihr dafür belohnt werden. \n\nUnd jetzt an die Arbeit!", objectives = "Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[90] = { title = "Gewürzter Wolfskebab", description = "Gewürzter Wolfskebab ist eine Spezialität des Hauses! Natürlich kann ich Euch welchen machen. Aber ich brauche erst die Zutaten dafür. Bringt mir 10 magere Wolfflanken sowie Würzkräuter aus Stormwind. Hier im Wald streifen so viele Wölfe herum, da werdet Ihr kein Problem haben, an die Wolfflanken zu kommen, da bin ich mir sicher. Und für die Kräuter sucht ihr am besten Felicia Gump in ihrem Blumenladen im Kanaldistrikt von Stormwind auf.", objectives = "Beschafft Euch 10 magere Wolfflanken und Würzkräuter aus Stormwind und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[91] = { title = "Das Gesetz des Solomon", description = "Ein Feind Stormwinds hat sich im östlichen Vorläufer des Rotkammgebirges niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um unsere Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen Morganth.\n\nMorganth kontrolliert jetzt den Schattenfellklan. Die Gnolle tun alles, was er ihnen befiehlt. Wie es das Gesetz von Seenhain vorsieht, steht auf die Unterstützung eines im Königreich gesuchten Verbrechers die Todesstrafe.\n\nDiese abscheulichen Gnolle verdienen den Tod!\n\nGebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", objectives = "Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[92] = { title = "Rotkammgulasch", description = "Ich würde liebend gern Rotkammgulasch für Euch kochen. Aber es gibt da ein kleines Problem. Erst kürzlich musste ich während des Orcaufstands eine ganze Brigade von Soldaten der Armee von Stormwind verpflegen. Jetzt ist meine Vorratskammer leer. Aber wenn Ihr mir die Zutaten besorgt, dann mache ich das gern für Euch.\n\nBringt mir einfach 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", objectives = "Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[93] = { title = "Schwärzliche Krebsküchlein", description = "Ich verrate Euch ein kleines Geheimnis: Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht! Ich weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Wenn Ihr mir einige klebrige Spinnenbeine bringt, dann zaubere ich Euch ein paar.\n\nIch habe gehört, dass sich Giftweberspinnen ausgezeichnet dafür eignen - sie haben ihr Nest im Norden, zwischen dem Vorgebirge und dem Fluss.", objectives = "Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[94] = { title = "Ein wachsames Auge", description = "Mein Widersacher Morganth ist ein böser Magier von großer Macht, der im Turm von Ilgalar im Rotkammgebirge lebt. Ich habe eine Methode entwickelt, mit der ich ihn ausspionieren kann: Mit dem Auge von Azora ist es mir möglich, ihn von weitem zu sehen.\n\nDoch um seine Gedanken zu erforschen... ja, dazu benötige ich noch weitere Hilfe.\n\nWenn Ihr gewillt seid, dies zu tun, dann bringt meine Glyphe von Azora zum Turm von Ilgalar. Legt sie auf die Löwenstatue in der Nähe des Turms.\n\nSobald dieses getan ist, wird die Macht von Azora mir Visionen von Morganths zukünftigen Plänen gewähren.", objectives = "Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[95] = { title = "Svens Rache", description = "Früher arbeitete ich auf einem der Höfe im Südosten... bis einmal in meiner Abwesenheit Dunkle Reiter vom Gebirgspass der Totenwinde herunterkamen, meinen Hof überfielen und meine Familie abschlachteten.\n\nAls ich zurückkehrte, sah ich eine schattenhafte Gestalt, die sich bei meiner Scheune herumtrieb und dort etwas vergrub. Er floh, ehe ich ihn erreichen konnte, und ich hatte keine Zeit, mich mit ihm aufzuhalten, da ich den Dunklen Reitern dicht auf den Fersen war. Und so habe ich nie entdeckt, was die Gestalt dort versteckte.\n\nWenn Ihr herausfinden könntet, was jene schattenhafte Gestalt dort vergrub, dann wäre ich Euch dankbar. Das Versteck befindet sich hinter dem alten Baumstumpf in der Nähe meiner Scheune.", objectives = "Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[96] = { title = "Ruf des Wassers", description = "Nehmt Splitter. Nehmt Splitter und gebt Leben.\n\nGebt Leben und versteht. Versteht, Wasser ist Leben... Verderbnis beendet Leben.\n\nIhr schützt und gebt Leben mit der Macht des Wassers.", objectives = "Bringt den Splitter des Wassers in das Brachland zu Islen Waterseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[97] = { title = "Die Legende von Stalvan", description = "Kommandant Ebonlocke muss unverzüglich erfahren, dass die Handschriften identisch sind, $N! Ihr Verdacht hat sich also bestätigt.", objectives = "Berichtet Kommandant Ebonlocke die Neuigkeiten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[98] = { title = "Die Legende von Stalvan", description = "Stalvan Mistmantle hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht. Das Licht allein weiß, welche schmutzigen Pläne er jetzt ausheckt. Deswegen brauche ich Eure Hilfe, $C. Begebt Euch zu seiner Hütte ein kleines Stück nördlich der Stadt und schaltet Stalvan ein für alle Mal aus.\n\nSobald die Tat vollbracht ist, begebt Euch zu Madame Eva und zeigt Ihr den Ring seiner Familie. Schließlich war es ihre Vorahnung, die zu dieser entsetzlichen Entdeckung führte. Doch jetzt kann ganz Dunkelhain dank ihr wieder ruhiger schlafen.", objectives = "Tötet Stalvan Mistmantle und zeigt Madame Eva den Ring seiner Familie.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[99] = { title = "Arugals Torheit", description = "Je mehr ich über Arugals Magie erfahre, umso mehr wächst meine Verachtung für diesen jämmerlichen Narren. Bald werde ich meine Studien zu seiner so genannten 'Arznei' beendet haben.\n\nMein Wissen wird vollständig sein, sobald ich herausgefunden habe, welche Verzauberung die seltsamen Zustände in Pyrewood verursacht. Tagsüber scheinen die Arbeiter dort ganz gewöhnliche Menschen zu sein. Doch sobald die Sonne untergeht, verwandeln sich die Dorfbewohner in Moonrage-Worgs.\n\nIch muss Energie aus den verzauberten Fesseln ziehen, die Arugal auf sie gewirkt hat. Bringt mir 6 verzauberte Pyrewood-Fesseln, $N.", objectives = "Bringt Dalar Dawnweaver 6 Pyrewood-Fesseln zum Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[100] = { title = "Ruf des Wassers", description = "Noch während die Zauberformel, die Ihr gesprochen habt, verhallt, zuckt ein Meer von Lichtern um Euch herum auf. Das Zischen der Wassertropfen, die mit den Flammen in Berührung kommen, lässt nach und Eure überreizten Sinne spüren, wie die verderbten Geister in Eurer Nähe vernichtet werden.", objectives = "Sprecht mit der schwachen Wassermanifestation im Silberwald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[101] = { title = "Das Totem des Gegenschlages", description = "Nun, da übernatürliche Mächte den Wald durchziehen, besteht ganz zweifellos die Notwendigkeit, sich zu schützen, $N. Leise flüstern mir die Winde von einer großen Gefahr, die auf Euch lauert und der Ihr Euch in nicht allzu ferner Zukunft gegenübersehen werdet.\n\nAuch ein tapferer $C wie Ihr sollte sich schützen. Falls Ihr dies wünscht, so bringt mir 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift. Dann stelle ich Euch ein Totem des Gegenschlages her und belege es mit einem Zauber, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", objectives = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[102] = { title = "Auf Patrouille durch Westfall", description = "Stormwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen. Wir, die wir früher Bauern waren, werden Widerstand leisten.\n\nEure Aufgabe, so Ihr sie denn annehmt, wird es sein, im Grasland von Westfall auf Patrouille zu gehen. Spürt die widerwärtigen Gnolle auf, die augenscheinlich mit den Dieben aus den Todesminen zusammenarbeiten, und tötet sie. Bringt mir 8 Gnolltatzen und ich werde Euren Mut zu belohnen wissen.", objectives = "Bringt 8 Gnolltatzen auf die Späherkuppe zu Captain Danuvin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[103] = { title = "Bewahrer der Flamme", description = "Die Nacht, in der die Familie des Leuchtturmwärters starb, war schrecklich. Hilflos musste ich mit ansehen, wie Old Murk-Eye den Angriff befehligte. Doch was geschehen ist, ist geschehen. Nun sorge ich mich vor allem um das Leben der Seeleute, die das große Meer besegeln und deren Schiffe den trügerischen Felsen vor der Küste gefährlich nahe kommen. Da hier niemand mehr lebt, der die Flamme bewacht, obliegt die Verantwortung nun mir.\n\nHelft mir dabei, die Fackel am Leuchten zu erhalten, und bringt mir 5 Fläschchen Öl von den Erntemonstern.", objectives = "Bringt 5 Fläschchen Öl zu Captain Grayson beim Leuchtturm von Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[104] = { title = "Bedrohung an der Küste", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Old Murk-Eye die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Old Murk-Eye brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Old Murk-Eye, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", objectives = "Bringt Captain Grayson am Leuchtturm von Westfall eine Schuppe von Old Murk-Eye.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[105] = { title = "Weh dir, Andorhal", description = "Endlich ist die Zeit gekommen Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nDer Lich - Araj der Zerstörer - herrscht von innerhalb der Ruinen der Stadt aus. Er wird von zahlreichen Angehörigen der Geißel bewacht, die über die Überreste des Stadtzentrums wachen, auch sein Gefolge an Leibwächtern ist ausgezeichnet. Ihr werdet einige Verbündete brauchen, um auch nur einen Hauch von einer Chance zu haben, sich ihm gegenüber stellen zu können.\n\nVernichtet Araj, $N, und bringt mir einen Splitter seines Phylakteriums als Beweis!", objectives = "Bringt den Splitter von Arajs Phylakterium zu Hochexekutor Derrington ins Bollwerk in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[106] = { title = "Junge Liebende", description = "Oh, ein Fluch lastet auf mir! Mein Herz gehört Tommy Joe Stonefield, aber unsere Familien sind aufs Ärgste miteinander verfeindet. Daher kann ich mich nicht mit ihm treffen, obwohl ich mich doch so sehr danach sehne, sein geliebtes Gesicht zu sehen!\n\nBitte nehmt diesen Brief und gebt ihn Tommy Joe. Normalerweise hält er sich am Fluss im Westen des Hofs der Stonefields auf, das ist auch von hier aus genau westlich.", objectives = "Gebt Tommy Joe Stonefield Maybells Liebesbrief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[107] = { title = "Nachricht an William", description = "Ich möchte wetten, William Pestle hat einen Trank, der unsere beiden Liebenden zusammenbringen kann.\n\nHier, bringt William diese Nachricht. Er wohnt im Gasthaus Zur Höhle des Löwen in Goldhain.", objectives = "Bringt Oma Stonefields Nachricht zu William Pestle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[109] = { title = "Meldung bei Gryan Stoutmantle", description = "Es scheint mir, $C, als hättet Ihr schon etliche Kämpfe überstanden. Falls Ihr das noch nicht getan habt, solltet Ihr Euch bei Gryan Stoutmantle melden. Er ist der Anführer der Volksmiliz, die es sich zur Aufgabe gemacht hat, das Ackerland von Westfall zu beschützen. Ich möchte wetten, er könnte Eure Hilfe gebrauchen. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", objectives = "Sprecht mit Gryan Stoutmantle. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[110] = { title = "Insektenteil-Analyse", description = "Ich werde einige Zeit brauchen, um Scrimshanks Feldmesserausrüstung durchzusehen... und seine persönlichen Angelegenheiten zu regeln. Mein Bauch sagt mir, dass dies nicht der letzte Verlust ist, den wir durch die Käfer hinnehmen müssen.\n\nGeht bitte zu Alchimist Pestlezugg, um zu sehen, ob er etwas mit den Insektenteilen anfangen konnte, die wir ihm geschickt haben. Wenn sie fertig sind, bringt sie mir.", objectives = "Begebt Euch nach Gadgetzan zu Alchimist Pestlezugg und erkundigt Euch nach der Analyse der Insektenteile.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[111] = { title = "Gespräch mit Oma", description = "Bitte sprecht mit meiner Großmutter, $n. Wenn irgendjemand einen Weg weiß, wie ich mit Maybell zusammen sein kann, dann ist sie das.\n\nIhr findet sie in unserem Haus, östlich von hier.", objectives = "Sprecht mit Oma Stonefield.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[112] = { title = "Die Suche nach dem Tang", description = "Ich könnte einen Unsichtbarkeitsschnaps für Maybell brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, brauche ich etwas Kristalltang.\n\nDieser Tang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs gesammelt. Geht und schaut, ob die Murlocs am Kristallsee welchen haben. Der Kristallsee liegt ein kleines Stück östlich von Goldhain.", objectives = "Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[113] = { title = "Insektenteil-Analyse", description = "Der Leitende Feldmesser Fizzledowser muss diesen Bericht sofort sehen. Eigentlich muss jeder, der lesen kann, diesen Bericht sehen. Wir stehen einer großen und ernsten Bedrohung gegenüber, die nicht nur Tanaris und Gadgetzan, sondern das ganze südliche Kalimdor betrifft, wenn wir nichts unternehmen. Möglicherweise ist sogar ganz Azeroth gefährdet. Dieses Ding macht nicht den Eindruck, als würde es das Interesse verlieren.\n\nLasst Fizzledowser ein Duplikat des Berichts anfertigen, den Ihr dann an Eure Verbündeten verteilen könnt. Jeder muss von dieser Bedrohung erfahren!", objectives = "Bringt den Bericht nach Gadgetzan zum Leitenden Feldmesser Fizzledowser. Lasst Euch von ihm eine Kopie des Berichts geben, wie Alchimist Pestlezugg gefordert hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[114] = { title = "Die Flucht", description = "Bringt der jungen Maybell diesen Unsichtbarkeitsschnaps. Seine Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.", objectives = "Bringt Maybell Maclure den Unsichtbarkeitsschnaps.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[115] = { title = "Schattenmagie", description = "Von den Orcs des Blackrockklans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt und es ist von äußerster Wichtigkeit, dass wir diese dämonbesudelten Gegenstände aus dem Konflikt entfernen.\n\nDurchsucht erschlagene Schattenzauberer der Blackrock nach Mitternachtskugeln und bringt sie mir. Ich werde die Kugeln dann vernichten lassen, denn ohne sie wäre die Welt ein wesentlich besserer Ort.", objectives = "Bringt 3 Mitternachtskugeln nach Seenhain zu Marshal Marris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[116] = { title = "Trockene Zeiten", description = "Mir werden hier gerade die Vorräte knapp, $N. Alle Flaschen sind fast leer, und die letzte Schnapslieferung hätte schon längst hier eintreffen sollen. Die Orcinvasion ist einfach die Hölle.\n\nVielleicht könnt Ihr Euch ja für mich an die Arbeit machen?\n\nIhr müsst für mich bei Grimbooze Donnerbräu in den Westfall-Hügeln ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Stormwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch mit süßem Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", objectives = "Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[117] = { title = "Donnerbräu", description = "Ihr müsst eilen, $gmein Freund:Madame;, sollt nicht ruhen, noch rasten, \nDenn für unser Lagerbier lohnt sich's zu hasten. \nEs schmeckt allen Männern, es schmeckt allen Frauen - \nDoch ich brauche noch Hopfen, um das Bier zu brauen.", objectives = "Bringt Grimbooze Donnerbräu 5 Hopfen, damit er sein besonderes Bier brauen kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[118] = { title = "Der Preis für Hufeisen", description = "Ich habe so viel Eisen dafür verwenden müssen, die Wachen von Stormwind auszurüsten, dass ich nicht mehr genug Eisen übrig habe, um die Pferde im Stall zu beschlagen!\n\nBringt diese Nachricht zu Schmied Argus nach Goldhain. Darin erkläre ich ihm mein Problem und bitte ihn um eine Lieferung Hufeisen.", objectives = "Bringt Verners Nachricht zu Schmied Argus nach Goldhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[119] = { title = "Zurück zu Verner", description = "Gut, er soll seine 50 Hufeisen haben.\n\nHier sind sie, schön in eine Kiste verpackt und bereit zum Abmarsch. Sagt Verner, dass es ein Vergnügen war, mit ihm Geschäfte zu machen, und sagt ihm, dass er unbedingt die Nachricht lesen soll, die ich ihm an die Kiste geheftet habe!", objectives = "Kehrt zu Verner Osgood ins Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[120] = { title = "Botschaft nach Stormwind", description = "Wir leben in schwierigen Zeiten, $C. Unsere Ortschaft ist einer ständigen Belagerung ausgesetzt. Wenn wir keine Verstärkung bekommen, ist unsere Niederlage so gut wie besiegelt. Die Botschaft, die ich Euch nun anvertrauen werde, ist von äußerster Wichtigkeit. Bringt diesen Bericht unverzüglich zu General Marcus Jonathan nach Stormwind. Sobald Ihr die Nachricht abgeliefert habt, kehrt umgehend zu mir zurück und überbringt mir alle Neuigkeiten, ganz gleich, ob gut oder schlecht. \n\nDoch nun eilt!", objectives = "Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Stormwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[121] = { title = "Botschaft nach Stormwind", description = "Während ich auf Antwort vom König warte, möchte ich, dass Ihr diesen Brief zu Magistrat Solomon bringt. \n\nWeggetreten, $C!", objectives = "Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[122] = { title = "Bauchschuppen", description = "Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat. Wenn Ihr mir 6 solcher Schuppen besorgt, dann kann ich mit einem Teil davon Argus bezahlen - und habe dann immer noch einen Rest übrig, aus dem ich etwas für Euch herstellen kann.\n\nSchwarze Großdrachenwelpen fliegen häufig über das Gebiet südlich von Seenhain, aber sie wandern auch gern herum. Haltet einfach die Augen offen und jagt sie, wenn Ihr sie seht.", objectives = "Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Osgood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[123] = { title = "Der Sammler", description = "Bei der Notiz handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des Waldes von Elwynn erhalten soll.\n\nAus dem Plan geht hervor, dass sich der Sammler anscheinend in der Nähe vom Brackwell-Kürbisbeet in Ost-Elwynn aufhält.\n\nDas klingt, als sei es wichtig. Ihr solltet Marshal Dughan in Goldhain davon berichten.", objectives = "Begebt Euch zu Marshal Dughan nach Goldhain und gebt ihm den Zeitplan des Sammlers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[124] = { title = "Das Bellen der Gnolle", description = "Als ob Orc-Angriffe nicht genug wären! Jetzt schleichen auch noch Gnoll-Schläger und Gnoll-Mystiker auf dem Hügelkamm nördlich von meinem Stall herum und fallen meine Pferde an, wenn diese sich auch nur etwas zu weit vom Stall entfernen...\n\nWenn Ihr diese Gnolle beseitigen könntet, wären meine Pferde und ich Euch sehr dankbar.", objectives = "Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Osgood zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[125] = { title = "Die verlorenen Werkzeuge", description = "Ich könnte hier wirklich etwas Hilfe gebrauchen, $n. Jetzt, wo die Stadt belagert wird, bekommen wir hier nur schwer Nachschub. Meine Werkzeuge sollten mit dem Karren von Goldhain aus angeliefert werden, aber die Brücke wurde in die Luft gejagt. Also legten wir die Werkzeuge in ein Boot, aber die Orcs beschossen es mit einem Katapult und trafen auch noch. Na, und bei meinem Pech ist mein Werkzeugkasten natürlich geradewegs bis auf den Grund des Sees gesunken.\n\nWenn Ihr mir meinen Werkzeugkasten wiederbeschafft, $n, dann soll es Euer Schaden nicht sein.", objectives = "Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[126] = { title = "Geheul in den Hügeln", description = "Die Gnolle sind immer noch da draußen, $n. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.\n\nTötet Jauler und vertreibt sein Rudel in alle vier Winde! Bringt mir seine Tatze zum Beweis.\n\nAber seid vorsichtig! Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...", objectives = "Bringt Jaulers Tatze nach Seenhain zu Verner Osgood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[127] = { title = "Fischhandel", description = "Der Immerruhsee ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch - und ich habe bald keine mehr vorrätig!\n\nBringt mir 10 Stück, dann werden wir uns schon handelseinig werden. Und wenn Ihr nicht selbst angeln möchtet oder könnt - na ja, vielleicht bekommt Ihr die Fische ja von den Murlocs!", objectives = "Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[128] = { title = "Kopfgeld auf die Blackrocks", description = "Der Blackrockklan muss vernichtet werden. Der Feind ist in unser Land eingedrungen. Diese Berge unterliegen der Oberhoheit des Königs von Stormwind. Aus bestimmten Quellen haben wir erfahren können, dass die Anführer jeder Einheit im Klan \"Helden\" genannt werden. Ihr findet sie in ihrem Lager im Norden, ein kleines Stück westlich von der Straße, die in die brennende Steppe führt.\n\nMagistrat Solomon möchte diese garstigen Bestien tot sehen. Erschlagt 15 Helden der Blackrock und kehrt zu mir zurück.", objectives = "Tötet 15 Helden der Blackrock, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[129] = { title = "Ein geschenktes Mittagessen", description = "Könntet Ihr mir einen Gefallen tun? Ich habe für Wache Parker ein Mittagessen gemacht, aber er ist gerade auf Patrouille unterwegs... Er ist groß und stark und noch dazu eine Wache von Stormwind, also kann er auf sich selbst aufpassen, aber ich bin nur eine kleine Stadtbewohnerin - für mich ist das da draußen viel zu gefährlich!\n\nWenn Ihr ihm also sein Mittagessen bringt und anschließend wieder herkommt, dann bekommt Ihr auch ein Mittagessen von mir - umsonst! Parker patrouilliert die Straße, die in den Dämmerwald führt.", objectives = "Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[130] = { title = "Besuch im Kräuterladen", description = "Könnt Ihr Darcy ein paar Blumen von mir bringen, wenn Ihr wieder zu ihr geht? Die Blumen bekommt Ihr im Kräuterladen von Seenhain, am westlichen Ende des Ortes.\n\nAber wenn Ihr die Blumen holt, dann sagt Martie, der Kräuterkundigen, nicht, für wen sie bestimmt sind oder wer Euch beauftragt hat, ja?", objectives = "Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[131] = { title = "Narzissen für eine Dame", description = "Hier habt Ihr Euren Blumenstrauß. Ich habe Narzissen für Euch ausgesucht. Narzissen sind meine Lieblingsblumen.", objectives = "Gebt Darcy den Narzissenstrauß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[132] = { title = "Die Bruderschaft der Defias", description = "Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.\n\nBringt Stoutmantle diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann.", objectives = "Bringt Wileys Nachricht nach Westfall zu Gryan Stoutmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[133] = { title = "Ein Ghulbildnis", description = "Ich wohne so weit weg von der Stadt und dem Schutz, den sie bietet, dass es ein Wunder ist, dass die Ghuls und die wandelnden Toten mich noch nicht aufgefressen haben! Tatsächlich hat erst gestern ein Rudel Knochenkauer gegen die Wände meines Hauses gehämmert.\n\nIch möchte ein Bildnis herstellen - eine Art \"Vogelscheuche\", nur für Ghuls. Dafür brauche ich ein paar Ghulrippen. Die bekommt Ihr von Fleischfressern, Knochenkauern, Hirnfressern, Verfaulten und Seuchenverbreitern.\n\nWenn Ihr mir die Rippen beschafft, bezahle ich Euch in barer Münze.", objectives = "Sammelt 7 Ghulrippen und bringt sie zu Calvinius in seiner Hütte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[134] = { title = "Ogerdiebe", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, $n, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", objectives = "Bringt Calvinius' Kiste zu Calvinius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[135] = { title = "Die Bruderschaft der Defias", description = "Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach.", objectives = "Bringt Wileys Nachricht nach Stormwind zu Mathias Shaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[136] = { title = "Käpt'n Sanders Versteckter Schatz", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sander in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", objectives = "Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[138] = { title = "Käpt'n Sanders versteckter Schatz", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Ost'n halten. Östlich von der Straße die Steilhänge hoch. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr'n altes Fass mit Eurem nächsten Hinweis drin.", objectives = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[139] = { title = "Käpt'n Sanders Versteckter Schatz", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch bei dem Henkelkrug umguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", objectives = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[140] = { title = "Käpt'n Sanders Versteckter Schatz", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", objectives = "Findet Käpt'n Sanders Truhe und öffnet sie. Darin befindet sich Eure Belohnung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[141] = { title = "Die Bruderschaft der Defias", description = "Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Stormwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.\n\nIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!", objectives = "Bringt Shaws Bericht nach Westfall zu Gryan Stoutmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[142] = { title = "Die Bruderschaft der Defias", description = "Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. $N, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.", objectives = "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Stoutmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[143] = { title = "Botschaft nach Westfall", description = "Irgendetwas stimmt mit der Armee von Stormwind nicht. Sie hätte längst mit einem größeren Aufgebot hier sein müssen. Doch Zeit ist ein Luxus, den wir nicht haben. Ich werde nicht dabeistehen und tatenlos zusehen, wie die Bewohner von Seenhain ihr Leben geben. Nein. Ich muss versuchen, von anderer Stelle her Hilfe zu gewinnen. Ich habe gehört, dass sich in Westfall eine Volksmiliz gebildet hat.\n\nBringt dieses Hilfegesuch ihrem Anführer, Gryan Stoutmantle. Vielleicht können Stoutmantles Männer uns hier unterstützen, bis der König Verstärkung schickt.", objectives = "Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Stoutmantle bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[144] = { title = "Botschaft nach Westfall", description = "Es schmerzt mich, Magistrat Solomons Schreiben zu lesen. Offensichtlich hat er von dem Krieg, der hier in Westfall tobt, keine Ahnung. Sonst wäre er nicht so naiv, Hilfe von der Miliz zu erwarten. Wenn Stormwind nicht auch uns im Stich gelassen hätte, dann hätte es keinen Grund gegeben, die Miliz ins Leben zu rufen.\n\nBringt Eurem Herrn im Rotkammgebirge diese Antwort, $C. Und lasst ihn wissen, dass mir das Herz schwer wird, wenn ich an all die tapferen Leute denke, die ihr Leben verloren haben.", objectives = "Kehrt mit Gryan Stoutmantles Antwort zu Magistrat Solomon zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[145] = { title = "Botschaft nach Dunkelhain", description = "Ein weiteres Mal brauche ich Eure Hilfe. Ich habe an Lord Ebonlocke geschrieben und ihn gebeten, seine gut ausgebildete Nachtwache hierher zu schicken, damit diese bei der Verteidigung von Seenhain hilft. Es ist von ausnehmender Wichtigkeit, dass diese Nachricht ihn so bald wie möglich erreicht. Doch Ihr müsst äußerste Vorsicht walten lassen. Ebonlocke ist der Bürgermeister von Dunkelhain, und das liegt im Herzen des Dämmerwalds. Entfernt Euch nicht von der Straße.", objectives = "Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Ebonlocke nach Dunkelhain bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[146] = { title = "Botschaft nach Dunkelhain", description = "Wenn mir Magistrat Solomon nicht persönlich bekannt wäre, würde ich sagen, der Mann hat den Verstand verloren. Die Nachtwache nach Seenhain schicken, weil Stormwind die Hilfe verweigert? Die Nachtwache wurde gegründet, weil Stormwind uns verließ, als diese elende Magie langsam das Land überzog. Wenn ich meine Nachtwache jetzt fortschicke, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten.\n\nBringt Eurem Meister in Seenhain dieses Antwortschreiben.", objectives = "Kehrt mit Lord Ebonlockes Antwortschreiben zu Magistrat Solomon zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[147] = { title = "Menschenjagd", description = "Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.\n\nIm Abholplan steht, dass der Sammler sich am Brackwell-Kürbisbeet versteckt hält. Dort solltet Ihr nach ihm suchen.", objectives = "Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marshal Dughan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[148] = { title = "Lieferung aus Dunkelhain", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", objectives = "Sprecht mit Madame Eva.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[149] = { title = "Geisterhaarfaden", description = "Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.\n\nHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.\n\nUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...", objectives = "Bringt der blinden Mary den spektralen Kamm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[150] = { title = "Murlocwilderer", description = "Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält! Sie müssen verschwinden, ehe sie den ganzen See leer gefischt haben.\n\nGeht Murlocs jagen! Bringt mir 8 ihrer Flossen, dann habe ich vielleicht etwas für Euch...", objectives = "Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[151] = { title = "Die arme Graumähne", description = "Die arme Graumähne! Das arme Pferd ist völlig entkräftet nach all der Arbeit, die wir ihm aufgebürdet haben. Ich habe es gefüttert, ehe wir den Hof verließen, aber wir haben natürlich nicht damit gerechnet, dass uns der Wagen kaputtgehen würde. Wenn Ihr der Stute ein paar Hände voll Hafer vom Feld bringen könntet, wäre ich Euch dankbar.\n\nIch wette, es lässt sich rund um die Höfe in Westfall etwas Hafer finden; Ihr müsst nur diesen entsetzlichen Maschinen aus dem Weg gehen, die hier alles übernommen haben. Es gibt einige Höfe südwestlich von hier.", objectives = "Verna Furlbrow in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[152] = { title = "Ärger an der Küste", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", objectives = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Captain Grayson beim Leuchtturm von Westfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[153] = { title = "Rote Lederkopftücher", description = "Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.\n\nBringt mir 15 dieser Kopftücher, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", objectives = "Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[154] = { title = "Rückkehr mit dem Kamm", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", objectives = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[155] = { title = "Die Bruderschaft der Defias", description = "Stoutmantle denkt also wirklich, ein $R wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit. \n\nIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.\n\nSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.", objectives = "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Stoutmantle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[156] = { title = "Das Sammeln von Faulblüten", description = "Wenn Ihr mir ein paar Faulblüten bringt, dann kann ich Euch einen Kessel Zombiesaft brauen.\n\nFaulblüten wachsen an seltsamen Orten. Vor allem, habe ich gehört, findet man sie in den Schädeln von Skelettschrecken und Skelettsatanskreaturen - nicht, dass ich selbst schon mal nah genug dran war, um nachzusehen!\n\nDer Friedhof von Rabenflucht und die stillen Gärten sind voll von diesen Skeletten. Wenn Ihr die auf Eurer Suche nach den Faulblüten auch noch dezimiert, dann schlagt Ihr zwei Fliegen mit einer Klappe, und ganz Dunkelhain wäre Euch dankbar.", objectives = "Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[157] = { title = "Abliefern des Fadens", description = "Hier ist Euer Faden, $n. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.", objectives = "Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[158] = { title = "Zombiesaft", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne Zum roten Raben in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, $N. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", objectives = "Sprecht mit Schankwart Smitts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[159] = { title = "Saftlieferung", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", objectives = "Bringt Calvinius den Zombiesaft in seine Hütte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[160] = { title = "Ein Brief für den Bürgermeister", description = "Bringt diese Nachricht zu Ello Ebonlocke, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde, und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", objectives = "Bringt Calvinius' Brief zu Ello Ebonlocke, dem Bürgermeister von Dunkelhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[161] = { title = "Eine dunkle Bedrohung", description = "Falls mein Verdacht sich bestätigt, ist dies eine Art Sprengpulver. Es muss von einem Sprengstoffexperten analysiert werden, damit wir genau wissen, mit was wir es hier zu tun haben. Ashlan Stonesmirk wurde dem Regiment zugeteilt, das Dun Modr und den Thandol-Übergang bewachen soll. Ihr müsst für mich eine schwierige und gefahrvolle Reise auf Euch nehmen, $N.\n\nReist durch das Algaz-Tor, folgt der Straße durch das Sumpfland und sucht Stonesmirk in Dun Modr auf. Folgt meinem Rat: Bleibt auf den Straßen und lasst Euch nicht zum Anhalten bewegen!", objectives = "Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver nach Dun Modr zu Ashlan Stonesmirk, dem Sprengstoffexperten, bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[162] = { title = "Aufstieg der Silithid", description = "Ihr solltet mit diesem Bericht zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da diese Nachtelfen-Gelehrte namens Gracina Spiritmight. Sie hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und sie ist noch dazu Historikerin! Wenn Euch jemand dabei helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und noch viel wichtiger, wie sie zu stoppen ist, gebt ihr den Bericht. Wir werden die Hilfe brauchen.\n\nDas Letzte, was ich hörte, war, dass sie im Tempel des Mondes in Darnassus lebt.", objectives = "Bringt den Insektenanalysebericht nach Darnassus zu Gracina Spiritmight.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[163] = { title = "Rabenflucht", description = "Irgendetwas stimmt nicht in Rabenflucht, $n. Calor schwört, dass jemand - oder etwas - in den Gebäuden dort umgeht. Zwei Nächte in Folge hat er jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher habe er Licht in einem der Fenster gesehen, sagte er.\n\nWenn Euch, wie Ihr sagt, die Sicherheit des Dämmerwalds am Herzen liegt, dann findet heraus, welches Monster in Rabenflucht umgeht.", objectives = "Findet heraus, was in Rabenflucht umgeht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[164] = { title = "Lieferung an Sven", description = "Kennt Ihr Sven? Das ist mal ein Mann, der das Werk des Lichtes vollbringt! Er und seine Anhänger haben ein Lager am nordwestlichen Rand des Dämmerwalds.\n\nLeider sind sie so wenige, dass noch nicht einmal ein einziger Mann abkömmlich ist, um Vorräte aus der Stadt zu holen. Würdet Ihr diese Vorräte bei ihm abliefern?", objectives = "Liefert die Vorräte an Sven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[165] = { title = "Der Einsiedler", description = "Es gab einmal einen alten Mann, der recht häufig in die Stadt kam, um Vorräte einzukaufen, aber ich habe ihn jetzt schon ziemlich lange nicht mehr gesehen. Er lebt draußen in einer Hütte, von der aus man den Friedhof von Rabenflucht überblicken kann, wenn ich mich recht erinnere. Vielleicht solltet Ihr einmal nachsehen gehen, ob dort alles in Ordnung ist.", objectives = "Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[166] = { title = "Die Bruderschaft der Defias", description = "Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.", objectives = "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Stoutmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[167] = { title = "Oh Bruder...", description = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Moonbrook versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen ... na ja ... von den anderen hat seither niemand mehr etwas gehört.\n\nIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.", objectives = "Bringt Großknecht Thistlenettles Forscherliga-Abzeichen nach Stormwind zu Wilder Thistlenettle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[168] = { title = "Die Suche nach Andenken", description = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Moonbrook führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.", objectives = "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Stormwind zu Wilder Thistlenettle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[169] = { title = "GESUCHT: Gath'Ilzogg", description = "Gesucht! Gath'llzogg, Rädelsführer hinter den Angriffen der Blackrock auf Burg Steinwacht und den Überfällen auf die Ortschaft Seenhain. \n\nGath'llzogg ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Blackrockklans gegen die menschliche Bevölkerung. Die Orcplage muss um jeden Preis eingedämmt werden. Der tapferen Seele, die Magistrat Solomon den Kopf von Gath'llzogg übergeben kann, winkt eine großzügige Belohnung.", objectives = "Erledigt Gath'llzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[170] = { title = "Eine neue Bedrohung", description = "Ich hoffe, Ihr seid hier, um uns zu helfen, $C. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können.\n\nIch habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Coldridge-Tal keine Ausnahme. Sie sind kreuz und quer in den Hügeln im Südosten und in der Nähe des gefrorenen Sees gesehen worden.\n\nUnd das ist noch nicht alles. Vor ein paar Nächten haben sie unser Lager im Westen angegriffen und überrannt! \n\nWir haben hier zu wenig Leute, $gJungchen:Mädel;, und wir brauchen ein paar starke Arme, die dabei helfen, die Troggs zurückzutreiben.", objectives = "Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[171] = { title = "Tageseltern der Allianz", description = "Ihr wart die ganze Zeit so gut zu mir, $n. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön.\n\nIch wünschte, all die anderen Waisenkinder hätten das Glück, so tolle Dinge zu unternehmen, wie wir. Meint Ihr, wir können Craggle Schlingerkreisel wiederfinden und bekommen einen Schaumstoffschwertständer von ihm? Ich glaube, er schiebt noch immer seinen Karren an den Kanälen rund um den Handelsdistrikt herum. So könnten alle anderen im Waisenhaus ihren Spaß haben!\n\nDanach wird es Zeit für mich, nach Hause zu gehen.", objectives = "Kauft einen Schaumstoffschwertständer von Craggle Schlingerkreisel und bringt dann Euren Schützling in das Waisenhaus von Sturmwind zurück, indem Ihr die Pfeife des Menschenwaisenkindes an Waisenmatrone Nachtigall im Kathedralenviertel übergebt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[172] = { title = "Die Kinderwoche", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch $n, benutzt die Pfeife und trefft Euren Schützling.", objectives = "Benutzt die Pfeife des orcischen Waisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[173] = { title = "Worgs in den Wäldern", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Carevin hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Carevin an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Schattenwirkern der Nachtheuler im Schattenhain und im verlassenen Obstgarten.", objectives = "Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[174] = { title = "Der Blick zu den Sternen", description = "Mein Freund Cog, der Gnom, hat mir versprochen, mir beim Bau eines Gerätes zu helfen, mit dem ich in die Sterne blicken kann. Jenseits der Magie existiert eine Wahrheit, mit deren Hilfe sich die seltsame Verwandlung des Waldes erklären lässt.\n\nBringt mir eine Bronzeröhre, die von einem geschickten Ingenieur hergestellt wurde. Wenn man nach Cogs Blaupause geht, ist das der erste Schritt.", objectives = "Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[175] = { title = "Der Blick zu den Sternen", description = "Laut Cogs Blaupause brauche ich jetzt etwas, mit dem Licht reflektiert werden kann. Ich erinnere mich an eine Frau namens Mary, die hier in der Gegend eine gewisse Bekanntheit erlangte, weil sie immer einen Handspiegel bei sich trug. Vielleicht könnt Ihr diese Mary aufspüren und sie fragen, ob sie ihn uns für unser Vorhaben vielleicht leiht, weil wir ja eine reflektierende Oberfläche brauchen... Ich glaube, sie wohnte früher im südlichen Dämmerwald...", objectives = "Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[176] = { title = "GESUCHT: \"Hogger\"", description = "Gesucht: Hogger\n\nEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.\n\nDie Armee von Stormwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei Marshal Dughan in Goldhain vorlegen.", objectives = "Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnoll-Klaue zu Marshal Dughan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[177] = { title = "Der Blick zu den Sternen", description = "Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof \"Stille Gärten\".", objectives = "Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[178] = { title = "Wiederbeschaffung für Theocritus", description = "<Ihr hört eine körperlose Stimme:>\n\nIhr müsst nicht erschrecken. Ich bin Theocritus, Hochmagier des Turms von Azora im Wald von Elwynn. Der Anhänger, den Ihr in Händen haltet, ist ein Mittel zur Kommunikation zwischen den Schattenfellgnollen und Morganth, ihrem Meister.\n\nNach langen Monaten der Forschung glaube ich, dass nun auch ich durch diese Anhänger kommunizieren kann. Wenn Ihr diese Nachricht hören könnt, dann war mein Zauber erfolgreich.\n\nBringt mir diesen Anhänger und ich werde Euch für Eure Dienste belohnen.", objectives = "Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[179] = { title = "Zwergenausstatter", description = "Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?\n\nIch sag Euch, was da helfen würde: ein paar schöne, warme Handschuhe. Und weil ich so ein netter Kerl bin, geb ich Euch doch gern so ein Paar. Unter einer Bedingung, versteht sich.\n\nIhr müsst mir etwas Wolfsfleisch besorgen. Ist doch 'n guter Handel, oder? Ihr bringt mir etwas Wolfsfleisch und ich sorge dafür, dass Ihr Euch keine Frostbeulen an den Fingern holt. Na, was sagt Ihr?", objectives = "Sten Stoutarm hätte gern 8 Stücke zähes Wolfsfleisch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[180] = { title = "GESUCHT: Lieutenant Fangor", description = "Gesucht: Lieutenant Fangor\n\nBekannter Anführer des Gnollklans der Schattenfelle; arbeitet für Morganth, den Feind der Stadt und des Königreiches. Auf Geheiß von Magistrat Solomon wird der Tod dieses üblen Verräters an Stormwind gewünscht. Zeigt dem Magistraten seine Tatze zum Beweis, dass er tot ist.", objectives = "Tötet Lieutenant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[181] = { title = "Der Blick zu den Sternen", description = "Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.\n\nEs gibt da einen Oger namens Zzarc'Vul, der im Ogerhort im Süden des Dämmerwalds haust. Wenn Ihr könnt, bringt mir sein Monokel, dann werde ich das als unsere Linse verwenden.", objectives = "Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[182] = { title = "Die Trollhöhle", description = "Mein Bruder Senir und ich wurden in unterschiedliche Ecken von Dun Morogh entsandt, um dort die von den Trollen ausgehende Gefahr zu untersuchen. Der Senat hat mit den Troggs bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.\n\nNach allem, was ich gesehen habe, ist die Position der Trolle hier im Coldridgetal nicht sonderlich gut - sie sind vor allem in der südlichen Höhle zu finden. Ich würde sagen, die Armee brauchen wir nicht. Einige starke Arme sollten mehr als ausreichend sein.\n\nMöchtet Ihr vielleicht mithelfen? Ich bin ermächtigt, Euch für Eure Dienste eine Entschädigung anzubieten.", objectives = "Grelin Whitebeard möchte, dass Ihr 14 Trollwelpen der Frostmane tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[183] = { title = "Der Eberjäger", description = "Es geht doch nichts über einen Tag auf der Eberjagd, wie?\n\nNa ja, hier im Coldridgetal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich für mich geworden ist, auf die Jagd zu gehen.\n\nIch mach's kurz: Wenn Ihr mir dabei helfen könntet, einige der Eber zu töten, dann würde ich das zu schätzen wissen.", objectives = "Talin Keeneye möchte, dass Ihr 12 kleine Klippeneber tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[184] = { title = "Furlbrows Urkunde", description = "Dies ist eine Besitzurkunde für ein Stück Ackerland in Westfall. Es ist von einem gewissen Theodore Furlbrow und seiner Frau Verna unterzeichnet. Auf der Rückseite der Besitzurkunde stehen ein paar hastig hingekritzelte Worte:\n\n\"Wir haben Furlbrow etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet.\n\nUm die Furlbrows müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse.\"\n\nIhr denkt, die Furlbrows hätten ihre Besitzurkunde vielleicht gern zurück ...", objectives = "Bringt Furlbrows Besitzurkunde zu Bauer Furlbrow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[185] = { title = "Beherrschen der Tigerjagd", description = "Als ich noch ein kleines Mädchen war, brachte mein Vater mir die Kunst der Tigerjagd bei.\n\nIhr werdet feststellen, dass die jungen Katzen sich wesentlich leichter aufspüren und töten lassen. Deswegen fangen wir auch klein an. Man findet die jungen Tiger oftmals in der Nähe des Expeditionslagers.\n\nÜbt Euch im Fährtenlesen und seht zu, ob Ihr nicht einige der Wildtiere zur Strecke bringen könnt.", objectives = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 junge Schlingendorntiger tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[186] = { title = "Beherrschen der Tigerjagd", description = "Ihr macht Fortschritte, $C. Jetzt lasst uns sehen, wie Ihr Euch gegen die ausgewachsenen Katzen anstellt. Tötet diesmal 10 Schlingendorntiger.", objectives = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[187] = { title = "Beherrschen der Tigerjagd", description = "Jetzt werde ich den Einsatz erhöhen und Eure Fähigkeiten wirklich prüfen. Beweist mir, dass Ihr 10 alte Schlingendorntiger töten könnt. Wenn Ihr das schafft, dann seid Ihr bereit für Eure letzte Herausforderung, ehe ich Euch in Meister Nesingwarys Gegenwart $gzum Meisterjäger:zur Meisterjägerin; ernenne.\n\nNicht nur sind die alten Schlingendorntiger am schwierigsten zu finden, sie sind auch am schwierigsten zu besiegen.", objectives = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[188] = { title = "Beherrschen der Tigerjagd", description = "Hier ist die letzte Aufgabe, die ich Euch auferlegen werde. Wir sind schon seit Wochen einer schwer zu fassenden Tigerin auf der Spur. Wir nennen das Tier Sin'Dall. Vielleicht gelingt Euch ja, was noch kein $R vor Euch geschafft hat: Spürt Sin'Dall auf und bringt sie zur Strecke. Bringt mir ihre Tatze zum Beweis für Eure Leistung.\n\nAber die Tigerin aufzuspüren, wird nicht leicht sein.", objectives = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[189] = { title = "Ohren der Bloodscalp", description = "Verdammte Trolle! Sie haben im Dschungel schon etliche unserer Agenten getötet und ich habe bereits einige meiner besten Wachen in Scharmützeln mit ihnen verloren. Was das alles kostet! Wie soll ich das nur Baron Revilgaz erklären?\n\nEntschieden handeln... Denk nach, Kebok... Du bist auf den Posten, den du heute hast, nicht durch Rumsitzen gekommen... Ha, ich hab's! Ihr... $N, richtig? Ihr helft mir doch, oder? Es gibt auch Geld zu verdienen!\n\nFolgender Handel... Ihr bringt mir die Ohren von 15 Trollen der Bloodscalp und ich bezahle Euch gut dafür.", objectives = "Verschafft Euch 15 Ohren der Bloodscalp und bringt sie Kebok in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[190] = { title = "Beherrschen der Pantherjagd", description = "Wenn Ihr zusammen mit dieser Elitegruppe, die Hemet zusammengestellt hat, an der Jagd teilnehmen wollt, dann müsst Ihr erst beweisen, dass Ihr $gein fähiger Pantherjäger:eine fähige Pantherjägerin; seid. Aber wir fangen ganz einfach an, keine Sorge. Schauen wir mal, wie Ihr Euch beim Töten von 10 jungen Panthern anstellt.\n\nDie Tiere aufzuspüren ist nur die halbe Miete.", objectives = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 junge Panther tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[191] = { title = "Beherrschen der Pantherjagd", description = "Jetzt seid Ihr bereit, Euch an einen Gegner zu wagen, der eine Nummer schwieriger ist. Wenn Ihr Euch wirklich als würdig erweisen wollt, mit solchen Leuten wie den Großwildjägern zu verkehren, dann müsst Ihr beweisen, dass Ihr 10 Panther töten könnt.\n\nDiese Bestien sind schon etwas zäher. Die lassen sich nicht so leicht erlegen wie die Jungtiere, mit denen Ihr Euch bis jetzt abgegeben habt.", objectives = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Panther tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[192] = { title = "Beherrschen der Pantherjagd", description = "Jetzt kommt der schwierige Teil. Ein echter Pantherjäger beweist seine Fähigkeiten damit, dass er Schattentatzenpanther erlegt, die tödlichsten Vertreter ihrer Art im ganzen Schlingendorntal. Beweist uns, dass Ihr 10 dieser Bestien zur Strecke bringen könnt.\n\nUnd wenn Ihr glaubt, die seien schwer aufzuspüren, dann wartet nur, bis Ihr versucht, eine von ihnen zu erlegen...", objectives = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Schattentatzenpanther tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[193] = { title = "Beherrschen der Pantherjagd", description = "Ihr habt schon fast bewiesen, dass Ihr die Kunst der Pantherjagd meisterlich versteht. Schon seit längerem pirscht ein Panther namens Bhag'thera durch den Dschungel. Bis jetzt ist er unserer Jagdgesellschaft immer ausgewichen. Seht zu, ob es Euch mit Euren Fähigkeiten gelingt, den großen Bhag'thera zu töten.\n\nBringt mir den Fangzahn von Bhag'thera, dann habt Ihr Euch meinen Respekt redlich verdient!", objectives = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr ihm den Fangzahn von Bhag'thera bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[194] = { title = "Beherrschen der Raptorenjagd", description = "Soso, Ihr glaubt also, Eure Jagdfertigkeiten sind erstklassig? Das lässt sich ganz leicht feststellen. Zieht hinaus in den Dschungel und tötet 10 Schlingendornraptoren. Dann werden wir ja sehen, wie gut Ihr als Großwildjäger wirklich seid.\n\nUnd nein, ich werde Euch nicht sagen, wo Ihr sie finden könnt! Die Viecher aufzuspüren ist Teil der Aufgabe.", objectives = "Hemet Nesingwary möchte, dass Ihr 10 Schlingendornraptoren tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[195] = { title = "Beherrschen der Raptorenjagd", description = "Jetzt machen wir die Herausforderung ein wenig schwieriger und schauen mal, ob Ihr dem gewachsen seid. Begebt Euch in den Dschungel und erlegt 10 dieser elenden Schmetterschwanzraptoren. Zeigt uns, was Ihr so drauf habt!", objectives = "Hemet Nesingwary möchte, dass Ihr 10 Schmetterschwanzraptoren tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[196] = { title = "Beherrschen der Raptorenjagd", description = "Mal sehen, wie Ihr mit der nächsten Herausforderung fertig werdet. Dort draußen treibt sich eine sehr scheue Art von Raptoren herum. Wir nennen sie Dschungelpirscher. Sie sind sehr viel schwieriger aufzuspüren und zu erlegen als die anderen Arten, an denen Ihr Euch bisher versucht habt. Tötet 10 Dschungelpirscher, dann verrate ich Euch, wie Ihr zu einem noch besseren Jagderlebnis kommt.", objectives = "Hemet Nesingwary möchte, dass Ihr 10 Dschungelpirscher tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[197] = { title = "Beherrschen der Raptorenjagd", description = "Da Ihr Euch im Dschungel als so tatkräftig erwiesen habt, lasst mich Euch von einem wilden Raptor erzählen, den sogar ich nicht erlegen konnte. Ajeck hier nennt diesen verschlagenen Raptor Tethis.\n\nWenn Ihr Euch als $gwahrer Meister:wahre Meisterin; erweisen wollt, dann erlegt Tethis und bringt mir seine Kralle. Es wäre eine Leistung, die bisher noch keinem anderen Großwildjäger gelungen ist.", objectives = "Hemet Nesingwary möchte, dass Ihr Tethis tötet, einen schwer fassbaren, gefährlichen Raptoren des Schlingendorntals.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[198] = { title = "Vorräte für den Gefreiten Thorsen", description = "Hmm. Ja, es gibt tatsächlich etwas, das Ihr tun könntet. Lieutenant Doren und seine Leute oben im Norden warten auf ihre turnusmäßige Vorratslieferung von uns.\n\nDie Vorräte wurden noch nicht bei ihnen abgeliefert und jetzt, wo die Trolle ständig angreifen, brauche ich jemanden, der das erledigt. Dorens Lager liegt im Nordwesten der Straße, dort, wo man vom Dämmerwald aus ins Schlingendorntal kommt. Gebt die Vorräte dem Gefreiten Thorsen. Wenn er nicht im Lager ist, dann patrouilliert er südlich davon. Er wird sie in Empfang nehmen und verstauen.\n\nAber dass eines klar ist: Wenn Ihr versagt, dann müsst Ihr mir Ersatz leisten.", objectives = "Liefert die verschiedenen Goblin-Vorräte bei dem Gefreiten Thorsen ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[199] = { title = "Eine dunkle Bedrohung", description = "Ihr nehmt eine Probe von dem sonderbar riechenden Pulver.", objectives = "Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[200] = { title = "Buchmacher Herod", description = "Wenn Kurzen Thorsens Geheimnis kennt, dann haben wir einen Spion in unseren Reihen. Wir müssen herausfinden, wie das Geheimnis verraten werden konnte!\n\nThorsens Kontaktperson in Kurzens Lager war der Buchhalter Herod. Herod ist Kurzens Nachschuboffizier und weiß alles über den Betrieb in Kurzens Truppenlager. Wenn Ihr Herods Unterlagen oder Aufzeichnungen beschaffen könntet, dann finden wir vielleicht heraus, wie Thorsen entdeckt werden konnte.\n\nAls wir noch unter Kurzen dienten, war das Büro des Buchhalters im oberen Stock des einzigen zweistöckigen Gebäudes im Lager. Seine Aufzeichnungen sind vermutlich immer noch dort zu finden.", objectives = "Findet Buchhalter Herods Aufzeichnungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[201] = { title = "Untersuchung des Lagers", description = "Ich habe Berichte gehört, nach denen eine Gruppe von Jägern ihr Lager flussaufwärts vom Bergbaucamp der Venture Company am Nazferitisee aufgeschlagen hat. Das wäre mir normalerweise völlig egal, aber ich habe gehört, dass Hemet Nesingwary einer der Jäger dort sein soll. Das ist zwar absolut unwahrscheinlich, aber... na ja, er hat sehr gute Beziehungen, wenn Ihr wisst, was ich meine, und man kann nie vorsichtig genug sein.\n\nWollt Ihr nicht hin und Euch das Lager einmal anschauen, $N, und sehen, was die vorhaben?", objectives = "Lokalisiert das Jägerlager und teilt dann Krazek in Booty Bay mit, wo es sich befindet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[202] = { title = "Colonel Kurzen", description = "Ihr habt Euren Wert wieder und wieder unter Beweis gestellt und Euer Einfallsreichtum scheint sich mit dem von Kurzen selbst messen zu können. Ihr könntet die Rettung für unseren Rebellentrupp sein... falls Ihr Euch gegen Kurzen stellen und siegen könnt!\n\nEr erteilt die Befehle an seine Männer von tief aus dem Vorratslager heraus. Ihr müsst Euch Zutritt zu dieser Höhle verschaffen, an seinen Verteidigern vorbei, und dann Kurzen und seinen Führungsoffizieren gegenübertreten.\n\nLebt wohl, $n. All meine Hoffnung, ebenso das Schicksal meiner Männer, ruht in Euren Händen.", objectives = "Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Lieutenant Doren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[203] = { title = "Die zweite Rebellion", description = "Wir kämpfen einen aussichtslosen Kampf gegen Colonel Kurzen. Nicht nur, dass der Mann ein brillanter Taktiker ist, seine Männer sind uns auch noch zahlenmäßig mindestens 10 zu 1 überlegen! Um überleben zu können, müssen wir seine eigenen, auf Heimlichkeit basierenden Taktiken gegen ihn anwenden.\n\nBetretet sein Lager im Osten und tötet seine Leute. So viele Ihr könnt. Und verschwindet wieder, bevor seine Verstärkung Euch in die Zange nehmen kann.", objectives = "Tötet 15 von Kurzens Dschungelkämpfern.\n\nKehrt ins Rebellenlager zu Sergeant Yohwa zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[204] = { title = "Schlechte Medizin", description = "Um überhaupt eine Chance gegen Kurzen zu haben, müssen wir ihm die Möglichkeiten beschneiden, seine Truppen zu heilen. Er hat um sich eine große Anzahl an Medizinmännern versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und unsere Kämpfer mit Giftfarnextrakt vergiften.\n\nWir brauchen dieses Arzneien, um unsere eigenen Leute zu heilen, und wir brauchen eine Probe dieser Extrakte, damit wir sie untersuchen und unser eigenen Arzneien herstellen können. Sucht in Kurzens Truppenlager nach beidem: Seine Medizinmänner haben die Arzneien und die Extrakte werden vermutlich irgendwo in den Vorratskästen im Lager verstaut sein.", objectives = "Bringt Sergeant Yohwa im Rebellenlager 7 Dschungelarzneien und 1 Giftfarnextrakt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[205] = { title = "Troll-Hexerei", description = "Während ich die Legenden studiere, die Ihr beschafft habt, sammelt bitte für mich die Gerätschaften der bösen Trollmagie. Begebt Euch in das Gebiet der Skullsplittertrolle, eines zweiten Stammes weit entfernt im Süden, und beschafft Euch dort Fetische der Skullsplitter von ihren Hexendoktoren und Mystikern.", objectives = "Bringt Bruder Nimetz 4 Fetische der Skullsplitter ins Rebellenlager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[206] = { title = "Mai'Zoth", description = "Kurzen mag vielleicht tot sein, doch das, was ihn zum Bösen trieb, ist noch am Leben! Mittels meiner Studien habe ich Folgendes entdeckt: Ein Ogermagier namens Mai'Zoth lebt in einem Ogerhort in den östlichen Bergen des Schlingendorntals. Gerüchten zufolge wendet er Magie an, mit deren Hilfe er in die Gedanken anderer eindringen und diese kontrollieren kann, und ich bin mir sicher, dass er es war, der Kurzen verderbt hat.\n\nBleibt Mai'Zoth am Leben, dann beeinflusst er vielleicht noch andere und vielleicht würde dann sogar ein zweiter Kurzen entstehen.\n\nTötet ihn und bringt mir sein Gedankenauge, das Artefakt, mit dem er andere Wesen verderbt.", objectives = "Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[207] = { title = "Das Geheimnis um Kurzen", description = "Colonel Kurzen war einst ein großer, ein edler Mann - ich muss herausfinden, wie es zu seiner Entartung kommen konnte! Es ist möglich, dass er dem Einfluss von Trollmagie unterliegt. Um diesen Verdacht zu bestätigen, muss ich einige ihrer Legenden studieren.\n\nIn den Trollruinen des Schlingendorntals liegen 4 Schrifttafeln versteckt. Ich muss wissen, was auf diesen Tafeln geschrieben steht! Schreibt die Zeichen ab, die Ihr auf den Tafeln findet, und bringt mir die Abschriften.\n\nDie erste Schrifttafel befindet sich in den Ruinen von Bal'lal, die zweite im Finsteren Riff und die dritte und vierte Schrifttafel findet Ihr in den Ruinen von Zul'Kunda.", objectives = "Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[208] = { title = "Großwildjagd", description = "$N, Ihr seid $gein Jäger, der:eine Jägerin, die; unserer Gesellschaft wahrlich würdig ist. Von den Schlachtfeldern von Lordaeron bis in den tiefsten Dschungel hinein habe ich selten jemanden gesehen, der so geschickt mit den Waffen umgegangen ist wie Ihr.\n\nIhr habt die furchterregende Sin'Dall, den schwer fassbaren Bag'thera und die tückische Tethis erlegt. Doch die wahre Trophäe ist der Kopf von König Bangalash. Dieser weiße Tiger ist der Grund, warum ich hier bin. Ich habe schon seit geraumer Zeit ein Auge auf ihn geworfen. Wenn Ihr König Bangalash tötet, dann steht ein für alle Mal fest, dass Euer jägerisches Können von niemandem übertroffen wird.", objectives = "Hemet Nesingwary möchte, dass Ihr ihm den Kopf von König Bangalash, dem großen weißen Tiger, bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[209] = { title = "Hauer der Skullsplitter", description = "Es ist teuer und anstrengend, genug Tiger zu töten, um damit den Bedarf an Tigerzähnen für den Export auf die Inseln in den südlichen Meeren decken zu können. Glücklicherweise haben wir eine gewisse Technik entwickelt, mit deren Hilfe wir aus einfachem hornähnlichen Material nicht nachweisbare Fälschungen herstellen können.\n\nErstaunlicherweise eignen sich die Hauer von Skullsplittertrollen dafür am besten.\n\nUnd bevor Ihr irgendwas sagt - was der Käufer nicht weiß, macht ihn nicht heiß, hab ich nicht Recht? Bringt mir so viele Hauer wie möglich, damit wir mit der monatlichen Lieferung anfangen können!", objectives = "Besorgt 18 Hauer der Skullsplitter und bringt sie zu Kebok.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[210] = { title = "Kochen mit Krazek", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblin-Händler in Booty Bay einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart - bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek.", objectives = "Bringt Krazeks Spezialtopf zu Krazek, dem Goblin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[211] = { title = "Weh dir, Andorhal", description = "Endlich ist die Zeit gekommen, Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nIhr habt vielleicht einen Beschwörungskristall in den von Euch markierten Wachtürmen bemerkt. Wir glauben, dass diese dem Lich die Kraft geben, die er zur Kontrolle der Stadt benötigt. Ihr müsst alle vier ausschalten. Wird einer davon zerstört, dürfte das zweifellos weitere Truppen des Lichs auf den Plan rufen. Wenn alle vier vernichtet wurden, dürfte der Lich selbst auftauchen, um das Herz der Stadt zu verteidigen.\n\nVernichtet den Lich, $n, und bringt mir einen Splitter seines Phylakteriums als Beweis!", objectives = "Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Valorfist auf der Chillwindspitze in den westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[212] = { title = "Eine kalte Mahlzeit", description = "Eines meiner berühmtesten Gerichte ist gekühlter Basilisk an Limonenvinaigrette. Das Problem ist nur: Das Fleisch lässt sich unmöglich frisch halten und ich muss das Gericht heute Abend anlässlich des Geburtstags eines Edelmannes servieren!\n\nWenn Ihr mir also schnell einen gekühlten Basiliskenschenkel von einem frisch getöteten Kaltaugenbasilisken bringen könnt, dann schulde ich Euch ein Festessen, das eines Königs würdig wäre!\n\nKaltaugenbasilisken streifen durch die Stranddünen im Nordwesten des Schlingendorntals, also habt Ihr eine lange Reise vor Euch. Und macht schnell!", objectives = "Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.\n\n<Um diese Aufgabe erfolgreich abschließen zu können, dürft Ihr Euren Geist nicht freigeben.>", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[213] = { title = "Feindliche Übernahme", description = "Diesmal ist er zu weit gegangen! Schlimm genug, dass Gelriz dabei ist, die von den Handelsfürsten eingesetzten Moguln rauszudrängen, jetzt versucht er auch noch, den berüchtigtsten aller Piraten mit hineinzubringen!\n\nDas lässt Revilgaz sich nicht bieten und er hat mir aufgetragen, das Problem auf meine Weise zu lösen.\n\nWas meine Weise ist? Diebstahl, ganz einfach. Die Geologen der Venture Company zeigen ein auffälliges Interesse an den seltsamen blauen Kristallen, die sie bisweilen in den Minen finden. Bringt mir einige Proben dieser Steine von den Geologen; es ist mir völlig egal, was Ihr tun müsst, um an sie heranzukommen.", objectives = "Beschafft 8 gerommelte Kristalle und bringt sie nach Booty Bay zu Kebok.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[214] = { title = "Rote Seidenkopftücher", description = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.\n\nJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, $n.", objectives = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[215] = { title = "Geheimnisse im Dschungel", description = "Danke, dass Ihr mich gerettet habt, $N. Ich weiß, wie es aussieht, aber lasst mich bitte erklären!\n\nIch hatte von Lieutenant Doren den Auftrag erhalten, mich wieder Kurzens Männern anzuschließen. Ich sollte sie ausspionieren und den Rebellen Informationen bringen, die sie bitter benötigen. Was Ihr hier miterlebt habt, war das, was ich für meine Chance hielt, Kurzens Truppenlager zu infiltrieren. Ich habe mich geirrt und ich muss Euch nochmals danken, dass Ihr mich gerettet habt.\n\nDiese Mission war streng geheim, Ihr dürft also niemandem davon erzählen. Aber wenn Ihr mit Doren sprecht, dann wird der Euch alles erklären.", objectives = "Sprecht im Rebellenlager mit Lieutenant Doren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[216] = { title = "Hart auf hart", description = "Die Distelfellfurbolgs bedrohen unsere Expansion! Das Lager der Distelfelle östlich von uns blockiert den Weg zwischen uns hier und dem Splintertreeposten. Dieser Weg würde das Dorf Astranaar umgehen; ohne ihn überlassen wir der Allianz eine zusätzliche Möglichkeit der Ausbreitung.\n\n$N, wir dürfen keine Lücke in unseren Expansionspfaden erlauben!\n\nBegebt Euch ins Distelfelllager und dünnt die Furbolgs etwas aus. Ihr werdet für diese Aufgabe entschädigt werden, aber noch viel wichtiger ist, dass Ihr Eure Pflicht der Horde gegenüber tun werdet.", objectives = "Schaltet 12 Rächer der Distelfelle und 12 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Distelfelllager. Wenn das erledigt ist, kehrt zu Karang Amakkar in den Zoram'gar-Außenposten in Ashenvale zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[217] = { title = "Verteidigung der Länder des Königs", description = "$N, unsere Späher haben den Anführer des jüngsten Eindringens der Troggs ermitteln können. Es scheint, als folgten diese Bestien am Loch Modan einem Häuptling namens Grawmug. Grawmug wird jedoch aufs Schwerste bewacht. Zwei seiner Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite.\n\nWenn Ihr Euch dem gewachsen fühlt, $N, dann möchte ich, dass Ihr das Attentat auf Grawmug und seine beiden Schläger anführt. Wenn die Führungsriege der Troggs tot ist, dann haben wir vielleicht eine Chance, diese Bestien wieder unter die Erde zu treiben.", objectives = "Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Captain Rugelfuss im südlichen Wachturm Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[218] = { title = "Das gestohlene Tagebuch", description = "Mein Tagebuch! Sie haben es in die Höhle gebracht. Der, der es hatte, war ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht. Viel mehr konnte ich leider nicht sehen.\n\nIhr hattet ja mit den Trollen Erfolg, vielleicht könntet Ihr es mir wiederbeschaffen?", objectives = "Grelin Whitebeard möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[219] = { title = "Vermisst", description = "Freunde der Allianz! Endlich!\n\nHelft... bitte... \n\nDas Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet; ich selbst erhielt einen Schlag an den Kopf und alles wurde schwarz. Jetzt werde ich in dieser Höhle gefangen gehalten. Bitte helft mir; ich bin schwer verletzt.\n\nIch brauche Hilfe auf dem Weg zurück in die Stadt... bitte... Ihr seid meine letzte Hoffnung...", objectives = "Beschützt Corporal Keeshan auf dem Rückweg ins Rotkammgebirge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[220] = { title = "Ruf des Wassers", description = "Islen hat noch eine weitere Aufgabe für Euch, ehe Ihr zur Belohnung Euer nächstes Totem erhaltet. Die Phiole mit Wasser, die ich Euch gegeben habe, wird für diese Aufgabe gebraucht, um was auch immer es sich dabei handeln mag.\n\nGeht nun und sucht sie auf. Wir werden uns eines Tages wieder begegnen.", objectives = "Bringt die Phiole mit reinstem Wasser in das Brachland zu Islen Waterseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[221] = { title = "Worgs in den Wäldern", description = "Habt Ihr vielleicht schon festgestellt, dass einige größere Worgs zusammen mit den Schattenwirkern im Wald herumziehen? Nach allem, was wir wissen, machen diese Dunkelläufer den Großteil der Worg-Population aus.\n\nAuf meinen Wanderungen habe ich außerdem festgestellt, dass sie in den verlassenen Obsthain im Südwesten der Stadt eingefallen sind. Diese Worgs sind etwas zäher als die Letzten, denen Ihr begegnet seid.\n\nAlso seht Euch vor.", objectives = "Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[222] = { title = "Worgs in den Wäldern", description = "Eure früheren Leistungen haben mich überzeugt, dass Ihr in der Lage seid, Euch mit den zähesten Worgs zu messen, die sich in den Wäldern eingenistet haben.\n\nVon all den Worgs, die plötzlich hier zu finden sind, haben sich die Faulreißer und die Besudelten als die gefährlichsten herausgestellt. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nNoch aus weiter Entfernung sieht man die Lichter ihrer Feuer...", objectives = "Tötet für Calor aus Dunkelhain einige Worgs, und zwar 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[223] = { title = "Worgs in den Wäldern", description = "Hier, bitte schön, $n. Bringt Meister Carevin diese Nachricht.\n\n<Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.>\n\nNoch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.", objectives = "Bringt Calors Notiz zu Jonathan Carevin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[224] = { title = "Verteidigung der Länder des Königs", description = "Wir müssen den Loch beschützen, $N! Jetzt, wo so viele der Soldaten des Königs tapfer auf weit entfernten Schlachtfeldern kämpfen, sind wir nahe davor, an der Heimatfront überwältigt zu werden. Aus jedem Spalt graben sich Troggs an die Oberfläche! Die Trogg-Plage stellt für Ironforge die größte Gefahr dar. Diese widerwärtigen Mutanten müssen vernichtet werden.\n\nIhr, $gtapferer Abenteurer:tapfere Abenteurerin;, müsst Euch für uns hinauswagen und der Bedrohung durch die Troggs ein Ende bereiten. Erschlagt 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher und erstattet dann wieder Bericht.", objectives = "Gebirgsjäger Cobbleflint vom südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[225] = { title = "Das verwitterte Grab", description = "Auf dem verwitterten Grabstein steht einfach:\n\nMORGAN LADIMORE\n\n<Als Ihr den Ort weiter untersucht, stellt Ihr fest, dass die Erde über dem Grab kürzlich umgegraben wurde und dass ein guter Teil der Erde entfernt worden zu sein scheint...>", objectives = "Sprecht in Dunkelhain mit Sirra Von'Indi.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[226] = { title = "Wölfe auf den Fersen", description = "Sven und mir stehen jetzt gefährliche Tage ins Haus, wo doch der Totenbeschwörer im Osten sitzt und all das. Und weil wir hier draußen allein sind, müssen wir auch selbst jagen, wenn wir etwas essen wollen. Es kommt mir so vor, als würden jedes Mal, wenn ich mit etwas Fleisch zum Lager zurückgehe, verhungernde oder tollwütige Terrorwölfe aus dem Wald kommen, die auch etwas abhaben möchten. Ja, eines steht fest, das Leben hier draußen ist gefährlich!\n\nAber wenn Ihr einige der Wölfe für uns erledigen könntet, dann wäre das Leben für uns etwas leichter. Meist streunen sie nördlich und östlich von hier herum, in der Nähe des Flusses.", objectives = "Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[227] = { title = "Morgan Ladimore", description = "<Er sucht in den Regalen und kommt mit einem ledergebundenen Buch zurück.>\n\nWenn Ihr mehr wissen wollt, dann fragt Althea. Sie ist diejenige, die in letzter Zeit von dem... Ärger... mit ihm am meisten mitbekommen hat.", objectives = "Sprecht in Dunkelhain mit Kommandantin Althea Ebonlocke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[228] = { title = "Mor'Ladim", description = "Meine Späher berichten mir, dass Mor'Ladim durch den ganzen Dämmerwald wandert und auf dem Friedhof einen seltsamen, gewundenen Weg einschlägt. Wir haben ihn hinter dem Haus auf dem Hügel begraben, wisst Ihr, wo das ist?\n\nEs gibt nichts, was ich tun könnte, um Euch zu helfen, aber ich wünsche Euch viel Glück.", objectives = "Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Ebonlocke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[229] = { title = "Die überlebende Tochter", description = "Ich hätte Euch dies schon früher sagen sollen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... , unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", objectives = "Sprecht in Dunkelhain mit Behüterin Sarah Ladimore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[230] = { title = "Svens Lager", description = "Als Ihr durch den Haufen wühlt, findet Ihr ein kleines, schmutzbeflecktes Buch.\n\nDas Buch hat keinen Titel, aber... es enthält Informationen, die Sven bestimmt interessieren.", objectives = "Bringt das Buch von Svens Hof zu Sven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[231] = { title = "Die Liebe einer Tochter", description = "Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.\n\n<Jetzt hat sie Tränen in den Augen, als sie einen Ring von der rechten Hand zieht und ihn Euch übergibt.>\n\nUnd... danke, $n.", objectives = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[232] = { title = "Kurierdienst für Apothekerin Zinge", description = "Die Königliche Apothekenvereinigung benötigt Eure Hilfe. Hört gut zu und wir können beide von meinem Plan profitieren.\n\nApotheker Keever im nächsten Raum mag... begabt sein..., aber seine Forschungen könnten Früchte tragen, wenn sie von einem gewandten Forscher... oder einer gewandten Forscherin verfolgt würden. Zum Glück bin ich eine solche Forscherin. Bringt diese Bestellung zu Alessandro Luca, dem Eigentümer von Blaumond Dies-und-Das. Er wird Euch ein Testset geben. Wenn Ihr es habt, bringt es zu mir zurück und ich werde Euch Eure Aufgabe im Detail erläutern.", objectives = "Bringt die Bestellung nach Undercity zu Alessandro Luca.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[233] = { title = "Postbeförderung im Coldridgetal", description = "Hm, ich nehme nicht an, dass Ihr mir einen Gefallen tun würdet, $gJungchen:Mädchen;? Heute kam ein Stapel Briefe durch den Pass, aber ich habe nicht die Zeit, sie weiterzuleiten.\n\nSie sind alle an Talin Keeneye adressiert. Ihr findet ihn ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen.\n\nWas meint Ihr?", objectives = "Liefert den Stapel Briefe bei Talin Keeneye ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[234] = { title = "Postbeförderung im Coldridgetal", description = "Wenn ich mich recht erinnere, hat Grelin sein Lager im Südosten, ein Stück die Straße hinunter. Ich bin sicher, er wartet schon sehnsüchtig auf seine Post.", objectives = "Liefert den Brief bei Grelin Whitebeard ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[235] = { title = "Die Jagd in Ashenvale", description = "Achtung, junge Abenteurer! Die Wildnis von Ashenvale erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splintertreeposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Thunderheart im Splintertreeposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd in Ashenvale teilnehmen wollen!", objectives = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[237] = { title = "Verteidigung der Länder des Königs", description = "Gebirgsjäger Cobbleflint hat nur Gutes über Euch zu berichten gehabt, $R. Daher werde ich Euch eine Mission von äußerster Wichtigkeit anvertrauen. Wir müssen den Druck auf die eindringenden Trogg-Streitkräfte aufrechterhalten, bis unsere Brüder, die Zwerge, von der Front der Allianz zurückkehren.\n\nBegebt Euch in die südlichen Hügel und tötet 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher. Eure Angriffe werden uns etwas Zeit verschaffen. Erstattet Bericht, sobald Ihr die Aufgabe erfüllt habt.", objectives = "Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[238] = { title = "Kurierdienst für Apothekerin Zinge", description = "Das Set ist fertig, $n. Die Apothekerin Zinge wird es zweifellos so schnell wie möglich haben wollen. Bringt es ihr ohne Verzögerung und lasst sie wissen, dass ich die Kosten für das Set mit auf die Rechnung der Gesellschaft schreiben werde. Richtet ihr bitte außerdem meine wärmsten Grüße aus.\n\nAlso los, steht nicht einfach so rum. So ist nun mal das Leben eines einfachen Kuriers, stimmt's?", objectives = "Bringt das Feldprobenset nach Undercity zu Apothekerin Zinge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[239] = { title = "Hilfe für die Weststromgarnison", description = "Die Garnison an unserer westlichen Grenze berichtet von steigenden Aktivitäten der Gnolle und der Diebe. Sie bitten uns um die Entsendung weiterer Soldaten aus Stormwind... aber wir können einfach keine entbehren!\n\nWenn Ihr helfen könntet - wir könnten die Hilfe wirklich gebrauchen. Geht, sprecht mit Deputy Rainer in der Weststromgarnison und fragt ihn, was getan werden muss.\n\nDie Garnison liegt an der Straße im Westen. Wenn Ihr die Brücke über den kleinen Bach überquert habt, liegt sie auf der rechten Seite.", objectives = "Begebt Euch zur Weststromgarnison und sprecht mit Deputy Rainer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[240] = { title = "Rückkehr zu Jitters", description = "Und voilà - \"Krebs\"-Küchlein à la Grual!", objectives = "Kehrt mit den schwärzlichen Krebsküchlein zu Jitters zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[243] = { title = "Auf ins Feld", description = "Ihr werdet Euch in die Tanariswüste begeben und die Gewebebeschaffenheit der Basilisken, Skorpiden und Hyänen testen, die dort heimisch sind. Beschafft Gewebeproben und untersucht sie mit dem Testset; Ihr müsst davon ausgehen, dass eine Reihe der Proben unnütz sind. Ich benötige von jeder Kreaturenart acht akzeptable Proben.\n\nAußerdem verfügen die Goblins von Gadgetzan über eine Kraftquelle, die mit dieser Art von modifiziertem Set verwendet werden muss. Sprecht mit Chefingenieur Bilgewhizzle und erwerbt eine für das Set.\n\nKehrt erst zu mir zurück, wenn Ihr erfolgreich wart.", objectives = "Sprecht in Gadgetzan mit Chefingenieur Bilgewhizzle über eine Kraftquelle für das Testset.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[244] = { title = "Eindringende Gnolle", description = "Seid gegrüßt, $C. Meine Aufgabe ist es, auf diesem Stück Straße zu patrouillieren. Obwohl die Straße im Augenblick sicher ist, habe ich nördlich und östlich von hier einige Lager von Gnollen gesehen.\n\nSeenhain muss erfahren, dass die Gnollstreitkräfte sich sammeln! Meldet Euch bei Deputy Feldon in Seenhain und berichtet ihm von den Gnollen. Wenn Ihr dies tut, dann wird Feldon Euch bestimmt den Sold eines Spähers zahlen.\n\nGewöhnlich inspiziert Feldon das Gebiet südlich der Brücke nach Seenhain.", objectives = "Erstattet Deputy Feldon Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[245] = { title = "Gefahr auf acht Beinen", description = "Seid gegrüßt, $C. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.\n\nIch bitte Euch wirklich nur sehr ungern darum, aber Ihr seht aus, als könntet Ihr mit ihnen fertig werden. Ich kann Euch keine großen Schätze versprechen, aber ich kann Euch belohnen, wenn Ihr dabei helft, die dreckigen Biester auszurotten.\n\nAch, ein Ratschlag noch: Weicht ihrem Gift aus, wenn Ihr könnt.", objectives = "Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[246] = { title = "Einschätzung der Gefahr", description = "Wir können keinen der Männer hier entbehren, aber mit diesen Gnollen, von denen Ihr mir berichtet habt, muss etwas passieren.\n\nSpäht das südliche Rotkammgebirge nach Gnollen aus. Bedrängt sie, tötet so viele Ihr könnt und erstattet mir dann Bericht über ihre Anzahl. Gebt mir auch eine Einschätzung der Gefahr, die sie darstellen. Möglicherweise findet Ihr Lager dieser Gnolle entlang der südlichen Straße im Rotkammgebirge.\n\nTut dies für die Armee von Stormwind, $N, und Ihr erhaltet eine Belohnung.", objectives = "Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[247] = { title = "Die Jagd ist abgeschlossen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[248] = { title = "Weitere Beobachtungen", description = "Seit einer Weile schon beobachte ich den Turm von Ilgalar und ich habe herausgefunden, dass Morganth im Konflikt mit den Orcs von Burg Steinwacht liegt. Den Grund für ihren Streit kenne ich nicht, aber vielleicht könnt Ihr mir ja dabei helfen, diesem Rätsel auf die Spur zu kommen.\n\nNehmt eine weitere Glyphe von Azora und begebt Euch dann auf die Spitze des unversehrten Wachturms neben der Burg Steinwacht.\n\nFindet einen passenden Gegenstand, auf dem Ihr die Glyphe ablegen könnt. Eine Truhe oder ein Krug - irgendein Ort, an dem die Glyphe nicht auffällt - ist für meine Zwecke geeignet.", objectives = "Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.\n\nFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[249] = { title = "Morganth", description = "Nach langen Beobachtungen habe ich jetzt Morganths Pläne durchschaut.\n\nEr sucht nach der Sense von Elune... und vielleicht hat er sie bereits gefunden! Wenn dem so ist, dann werden das Rotkammgebirge und das Königreich Stormwind schon bald seine dunkle Macht zu spüren bekommen.\n\nIch selbst bin leider nicht bereit, mich gegen Morganth zu stellen, doch ich fürchte, er muss genau jetzt aufgehalten werden. Daher müsst Ihr Euch Zutritt zum Turm von Ilgalar verschaffen und Morganth entgegentreten.\n\nBesiegt ihn und bringt mir seinen Schattenanhänger. Wenn Ihr dies vermögt, dann schuldet das Königreich Euch viel.", objectives = "Besiegt Morganth.\n\nBringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[250] = { title = "Eine dunkle Bedrohung", description = "Den Sternen sei Dank, jemand sorgt sich um den Damm. Erst die Zerstörung des Thandol-Übergangs, dann die Plünderung von Dun Modr! Ich hege keinerlei Zweifel, dass der Damm das Ziel des nächsten Anschlags der Dunkeleisenzwerge sein wird. Der größte Teil meiner Sicherheitsleute wurde an die Front der Allianz versetzt, einschließlich meines besten Kontrolleurs.\n\nUnd deswegen brauche ich Euch, $N. Ich habe einige Pioniere der Dunkeleisenzwerge gesehen, die an der östlichen Rampe des Damms herumlungerten. Untersucht den Bereich und bringt einen Hinweis zurück.", objectives = "Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[251] = { title = "Übersetzung von Calvinius' Notiz", description = "Bringt den Zettel, den Ihr mir gabt, zu Sirra Von'Indi. Er ist sehr gelehrt und kennt viele Sprachen und alte Künste - wenn überhaupt jemand diese Nachricht übersetzen kann, dann ist er das.", objectives = "Bringt den Brief an Ello zu Sirra Von'Indi.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[252] = { title = "Übersetzung für Ello", description = "Oh je! Wenn das, was hier steht, wahr ist, dann hat Calvinius etwas... Unsägliches getan.\n\nBringt die übersetzte Notiz besser schnell zu Ello zurück.\n\nBeeilt Euch, denn ich fürchte, Unheil rollt bereits auf unsere Stadt zu...", objectives = "Bringt Lord Ello Ebonlocke den übersetzten Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[253] = { title = "Braut des Einbalsamierers", description = "Der Einbalsamierer... diesen Namen kennen wir aus einer Geschichte, die wir unseren Kindern erzählen. Er war ein freundlicher Alchimist, den der Tod seiner Frau Eliza in den Wahnsinn trieb. Er wollte sie wiederbeleben und so wandte er schwarze Magie an und pflanzte sein eigenes Herz in die Brust seiner toten Gattin ein.\n\nDies stellte Eliza wieder her, doch nun war sie verflucht... ein unstillbarer Hunger auf Menschenfleisch hatte sich ihrer bemächtigt und der Einbalsamierer musste sie in ihrem Grab liegen lassen.\n\nSeine Macht ruht in seinem Herzen. Findet das Grab seiner Frau, holt sein Herz und bringt es mir, solange es noch schlägt. Wenn Ihr dies tut, wird seine Macht gebrochen sein.", objectives = "Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Ebonlocke zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[254] = { title = "Graben in der Erde", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[255] = { title = "Söldner", description = "Zwei Monate! Zwei Monate, nur um dann aus Ironforge zu hören zu bekommen, dass eine Handvoll Soldaten zu unserer Verteidigung abgestellt wird, und zwei weitere Monate, bis sie ankommen! Schlimm genug, dass unsere Stadt ohne Schutz ist, aber die Ausgrabung und der Damm - der Damm! - sind ebenfalls allen Angriffen schutzlos ausgesetzt.\n\nIch habe also keine Wahl, scheint mir. Ich brauche gedungene Kämpfer.\n\nWie steht es mit Euch? Ihr seht mir tüchtig aus, $C. Eine Gruppe Oger hat im Nordosten des Sees ihr Lager aufgeschlagen. Vielleicht könntet Ihr ein paar weitere Kämpfer rekrutieren und uns dabei helfen, die Bedrohung für unsere Stadt zu beseitigen?", objectives = "Magistrat Bluntnose aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[256] = { title = "GESUCHT: Chok'sul", description = "Auf Befehl des Magistrats von Thelsamar:\n\nDer Tod von Chok'sul, dem Oger und mutmasslichen Anführer und Kopf hinter den Angriffen auf die Stadt Thelsamar, den Stonewroughtdamm und die Ausgrabungsstätte, wird unter allen Umständen gewünscht. Es darf zu jedem Mittel gegriffen werden, das notwendig ist.\n\nEine Barentschädigung kommt zur Auszahlung, wenn der Magistrat einen Beweis für Chok'suls Tod erhält.\n\nZuletzt wurde Chok'sul am Ogerlager im nordöstlichen Teil von Loch Modan gesehen.", objectives = "Tötet Chok'sul und bringt Magistrat Bluntnose seinen Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[257] = { title = "Das Prahlen eines Jägers", description = "Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid. Also nehmt's nicht zu schwer, wenn Ihr damit nicht fertig werdet.\n\nEin Schwarm Bussarde nistet hier am Loch Modan. Warum versucht Ihr nicht, einige von denen zu erledigen? Ich sag Euch was. Wenn Ihr meine Herausforderung annehmt und es Euch in 15 Minuten gelingt, dann gebe ich Euch meinen Bogen oder mein Gewehr.\n\n<Er mustert Euch abschätzig.>\n\nScheint ja nicht, als ob Ihr viel zu verlieren hättet.", objectives = "Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[258] = { title = "Die Herausforderung eines Jägers", description = "$nath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war.\n\nIhr solltet Euch mal an der Eberjagd versuchen. Glaubt mir, das sind andere Eber als im Coldridgetal, also solltet Ihr Euch vorsehen. Diesmal gebe ich Euch nur 12 Minuten.\n\nSeid nicht zu traurig, wenn Ihr versagt. Ich würde Euch das Hemd geben, das ich am Leibe trage, wenn Ihr es schaffen würdet!\n\nHabe ich Euch schon mal erzählt, wie ich an meine berühmte Narbe gekommen bin? Nein? Also, das war vor zwei Jahren...", objectives = "Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[261] = { title = "Auf dem Scharlachroten Pfad", description = "Ich werde offen mit Euch sein. Wir sind im Krieg mit der Geißel. Sie ist ein Übel, das unser Volk verdirbt und unser Land infiziert. Sie muss aufgehalten werden, bevor sie uns übermannt und unsere Welt mit Schatten überzieht. Wir vom scharlachroten Kreuzzug haben geschworen, die Geißel mit Leib und Seele zu bekämpfen.\n\nWenn Ihr auf unserer Seite steht, dann nehmt Euren Mut zusammen und beweist Eure Zugehörigkeit - zerstört die untoten Verheerer von Desolace im südlich gelegenen Tal der Knochen.\n\nTut dies, und der Kreuzzug wird Euch mit offenen Armen aufnehmen.", objectives = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[262] = { title = "Die Schattengestalt", description = "Ich muss wissen, wen ich in der Nacht, in der meine Familie ermordet wurde, in den Schatten habe herumschleichen sehen.\n\nBitte, $n, Ihr habt euren Einfallsreichtum bereits bewiesen. Bitte findet diese schattenhafte Gestalt. Ich muss wissen, was sie für Geheimnisse kennt!\n\nIch habe keine Hinweise, die Ihr nicht bereits hättet, aber hier - nehmt das Buch, das Ihr auf meinem Hof gefunden habt. Vielleicht können einige Stadtbewohner das Buch mit seinem Besitzer in Verbindung bringen.", objectives = "Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[263] = { title = "Verteidigung der Länder des Königs", description = "Die Gebirgsjäger sagen mir, dass Ihr recht tapfer und fähig seid, $N. Ein $R wie Ihr wird hier draußen gebraucht. Wir bekommen das Trogg-Problem einfach nicht unter Kontrolle. Die Reserve wurde zur Front gerufen, und wir sind hier auf uns allein gestellt. Aber jetzt seid ja Ihr hier, ein erfahrener $C, also wollen wir doch mal sehen, was Ihr ausrichten könnt.\n\nZieht los und tötet 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs. Wir werden sehen, ob Ihr Eurem Ruf gerecht werdet, $gTrogg-Töter:Trogg-Töterin;.", objectives = "Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[264] = { title = "Bis dass der Tod uns scheidet", description = "Dreckiger Abschaum! Lässt mich wegen seinem verdammten Kreuzzug hier sitzen. Nur, weil \"das Licht das Wichtigste ist, was wir gegen die Bedrohung durch die Untoten besitzen\".\n\nUnd was ist mit seinen Kindern?! Was ist mit MIR?! Nacht für Nacht hab ich hier gesessen und geduldig auf ihn gewartet ... hab immer den zweiten Platz hinter seiner verfluchten Pflicht eingenommen!\n\nTja, hier könnt Ihr sehen, was Euch \"Gerechtigkeit\" einbringt, $N! Er ist tot, und ich ertrage genau das, was er aufzuhalten versuchte!\n\nNehmt diesen Plunder und legt ihn auf seine Gruft in dem Grabmal. Ich will nichts mehr damit zu tun haben ... oder mit ihm!", objectives = "Legt Clarices Anhänger auf Yurivs Grab in Silberwald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[265] = { title = "Die Schattensuche geht weiter", description = "Hier habt Ihr Euer Buch zurück, $n, und viel Glück noch bei Eurer Suche. Vielleicht können Euch ja andere in der Stadt mehr Hinweise geben, wenn Ihr sie fragt.\n\nIch habe jedenfalls noch einen für Euch - obwohl der Autor dieses Buches in Dunkelhain fremd ist, wurde das Buch selbst hier gekauft.", objectives = "Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
